function backendTicketFactoryConfig() {
  const gate = paidPilotLaunchGateConfig();
  const gateByLabel = Object.fromEntries(gate.gates.map((item) => [item.label, item]));
  const tickets = BACKEND_TICKET_FACTORY_TEMPLATES.map((template, index) => {
    const gateItem = gateByLabel[template.gateLabel] || {};
    const score = clampNumber(Math.round((gateItem.score || 48) * 0.75 + (template.priority === "P0" ? 12 : template.priority === "P1" ? 18 : 24)), 18, 96);
    const priority = score < 60 ? "P0" : score < 76 ? template.priority : template.priority === "P0" ? "P1" : "P2";
    const tone = score < 60 ? "blocked" : score < 76 ? "draft" : "ready";
    const status = tone === "blocked" ? "Open blocker" : tone === "draft" ? "Design ready" : "Implementation ready";
    const blockers = (gateItem.blockers || []).slice(0, 2);
    const ticketId = ["NN", "BACKEND", "TICKET", String(index + 1).padStart(2, "0"), DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase();
    return {
      ...template,
      blockers,
      priority,
      score,
      status,
      ticketId,
      tone
    };
  });
  const averageTicketScore = Math.round(tickets.reduce((sum, ticket) => sum + ticket.score, 0) / tickets.length);
  const openP0 = tickets.filter((ticket) => ticket.priority === "P0" || ticket.tone === "blocked");
  const firstTicket = [...tickets].sort((a, b) => {
    const priorityRank = { P0: 0, P1: 1, P2: 2 };
    return (priorityRank[a.priority] - priorityRank[b.priority]) || (a.score - b.score);
  })[0];
  const score = clampNumber(Math.round(gate.score * 0.45 + averageTicketScore * 0.55 - openP0.length * 2), 18, 96);
  const posture = openP0.length
    ? "Engineering blockers open"
    : score >= 82
      ? "Pilot implementation pack ready"
      : "Ticket design active";
  const factoryId = ["NN", "BACKEND", "FACTORY", DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase();
  const readout = [
    { label: "Factory score", value: `${score}/100`, detail: posture },
    { label: "P0 tickets", value: String(openP0.length), detail: openP0[0]?.title || "No P0 blocker in this preview." },
    { label: "First ticket", value: firstTicket.title, detail: `${firstTicket.owner} | ${firstTicket.route}` },
    { label: "Source gate", value: `${gate.score}/100`, detail: gate.decision }
  ];
  const handoffRules = [
    "Each ticket must store backend-owned receipts or reviewer receipts before public UI can rely on the state.",
    "Paid access must come from verified events, never success URLs, screenshots, manual notes, or browser-local state.",
    "Blocked data stays out: PAN, folio, CAS, bank, UPI, card, OTP, gateway secrets, ARN/EUIN, client records, and private note bodies.",
    "Every ticket ships with acceptance tests, replay test, rollback or freeze rule, owner, and support-safe receipt view.",
    "Founder pilot stays capped until all P0 tickets pass and support, refund, entitlement, and privacy workflows are observable."
  ];
  return {
    averageTicketScore,
    factoryId,
    firstTicket,
    gate,
    handoffRules,
    openP0,
    posture,
    readout,
    score,
    tickets
  };
}

function backendTicketCloseout(factory) {
  const suffix = DATA_VERSION.replace(/-/g, "");
  const closeoutTickets = factory.tickets.map((ticket, index) => {
    const acceptanceScore = clampNumber(ticket.score + ticket.acceptance.length * 3 - ticket.blockers.length * 8, 20, 96);
    const receiptScore = clampNumber(Math.round(ticket.score * 0.5 + ticket.eventContract.length * 7), 20, 96);
    const freezeScore = clampNumber(ticket.summary.toLowerCase().includes("freeze") || ticket.acceptance.join(" ").toLowerCase().includes("freeze")
      ? ticket.score + 8
      : ticket.score - (ticket.priority === "P0" ? 4 : 0), 20, 96);
    const rollbackScore = clampNumber(ticket.summary.toLowerCase().includes("rollback") || ticket.acceptance.join(" ").toLowerCase().includes("rollback")
      ? ticket.score + 6
      : ticket.score - (ticket.priority === "P0" ? 6 : 1), 20, 96);
    const ownerScore = clampNumber(ticket.score + (ticket.priority === "P0" ? -3 : ticket.priority === "P1" ? 2 : 6) - ticket.blockers.length * 4, 20, 96);
    const gates = [
      { label: "Acceptance tests", score: acceptanceScore, proof: ticket.acceptance[0] || "Acceptance path required." },
      { label: "Receipt proof", score: receiptScore, proof: `${ticket.eventContract.length} event fields mapped.` },
      { label: "Freeze posture", score: freezeScore, proof: "Launch freeze state must be visible before closeout." },
      { label: "Rollback note", score: rollbackScore, proof: "Rollback or reversal path must be attached." },
      { label: "Owner signoff", score: ownerScore, proof: `${ticket.owner} owns final closeout.` }
    ].map((gate) => ({
      ...gate,
      tone: gate.score >= 80 ? "ready" : gate.score < 62 ? "blocked" : "draft"
    }));
    const score = clampNumber(Math.round(gates.reduce((sum, gate) => sum + gate.score, 0) / gates.length) - ticket.blockers.length * 2, 20, 96);
    const blockers = [
      ...ticket.blockers,
      ...(gates.filter((gate) => gate.score < 66).map((gate) => `${gate.label}: ${gate.proof}`)),
      ...(ticket.priority === "P0" && score < 82 ? ["P0 ticket cannot close until closeout score reaches 82/100."] : [])
    ];
    const status = blockers.length
      ? "Closeout blocked"
      : score >= 82
        ? "Closeout ready"
        : "Owner review";
    const tone = status === "Closeout ready" ? "ready" : status === "Closeout blocked" ? "blocked" : "draft";
    return {
      ...ticket,
      blockers,
      closeoutId: ["NN", "BACKEND", "CLOSEOUT", String(index + 1).padStart(2, "0"), suffix].join("-").toUpperCase(),
      gates,
      score,
      status,
      tone
    };
  });
  const readiness = clampNumber(Math.round(
    closeoutTickets.reduce((sum, ticket) => sum + ticket.score, 0) / closeoutTickets.length * 0.68 +
    factory.score * 0.22 +
    (100 - closeoutTickets.filter((ticket) => ticket.status === "Closeout blocked").length * 7) * 0.1
  ), 20, 96);
  const blockedTickets = closeoutTickets.filter((ticket) => ticket.status === "Closeout blocked");
  const readyTickets = closeoutTickets.filter((ticket) => ticket.status === "Closeout ready");
  const nextTicket = [...closeoutTickets].sort((a, b) => {
    const rank = { "Closeout blocked": 0, "Owner review": 1, "Closeout ready": 2 };
    return (rank[a.status] - rank[b.status]) || (a.score - b.score);
  })[0];
  const status = blockedTickets.length
    ? "Closeout blockers open"
    : readiness >= 84
      ? "Closeout pack ready"
      : "Owner closeout review";
  const tone = status === "Closeout pack ready" ? "ready" : blockedTickets.length ? "blocked" : "draft";
  const closeoutId = ["NN", "BACKEND", "TICKET", "CLOSEOUT", suffix].join("-").toUpperCase();
  const metrics = [
    { label: "Closeout readiness", value: `${readiness}/100`, detail: status },
    { label: "Ready to close", value: `${readyTickets.length}/${closeoutTickets.length}`, detail: "Tickets with tests, receipts, freeze posture, rollback note, and owner signoff." },
    { label: "Open blockers", value: String(blockedTickets.length), detail: blockedTickets[0]?.title || "No hard closeout blocker in this preview." },
    { label: "Next closeout", value: nextTicket.title, detail: `${nextTicket.score}/100 | ${nextTicket.owner}` }
  ];
  const sequence = [
    "Run ticket acceptance tests and attach the test result ID.",
    "Attach backend receipt proof, source receipt, payment receipt, or reviewer receipt as applicable.",
    "Confirm launch freeze posture: clear, frozen, rollback, or resume-ready.",
    "Attach rollback note, support-safe wording, and user-visible correction or notice when needed.",
    "Owner signs the closeout and the ticket moves from implementation-ready to release-ready."
  ];
  const receiptFields = [
    "closeout_id",
    "ticket_id",
    "owner_role",
    "acceptance_test_id",
    "receipt_proof_id",
    "source_or_payment_receipt_id",
    "freeze_posture",
    "rollback_note_id",
    "support_safe_summary_id",
    "blocked_data_scan",
    "reviewer_or_owner_signoff",
    "closed_at",
    "retention_policy"
  ];
  const ownerRules = [
    "A ticket can be designed without owner signoff, but it cannot close without one.",
    "P0 tickets need acceptance tests, replay proof, and a freeze or rollback decision before closeout.",
    "Support and privacy tickets need redaction proof before any evidence leaves the backend lane.",
    "Payment tickets need idempotency, refund, cancellation, settlement, and entitlement proof before paid access widens."
  ];
  const blockers = blockedTickets.length
    ? blockedTickets.map((ticket) => `${ticket.title}: ${ticket.blockers[0] || ticket.status}`)
    : ["No active closeout blocker in this preview. Keep real production closeout server-side and receipt-backed."];
  return {
    blockedTickets,
    blockers,
    closeoutId,
    metrics,
    nextTicket,
    ownerRules,
    readiness,
    readyTickets,
    receiptFields,
    sequence,
    status,
    tickets: closeoutTickets,
    tone
  };
}

function workerEndpointAcceptanceMatrix(factory = backendTicketFactoryConfig(), closeout = backendTicketCloseout(factory)) {
  const suffix = DATA_VERSION.replace(/-/g, "");
  const endpointMatrixId = ["NN", "WORKER", "ENDPOINT", "MATRIX", suffix].join("-").toUpperCase();
  const acceptanceBatchId = ["NN", "ENDPOINT", "ACCEPTANCE", "BATCH", suffix].join("-").toUpperCase();
  const monitorHandoffId = ["NN", "ENDPOINT", "MONITOR", "HANDOFF", suffix].join("-").toUpperCase();
  const releaseCloseoutId = ["NN", "ENDPOINT", "RELEASE", "CLOSEOUT", suffix].join("-").toUpperCase();
  const endpointMap = {
    "Receipt vault replay": { method: "POST", path: "/api/receipts/replay", service: "receipt-replay-worker", monitor: "receipt_replay.worker.completed" },
    "Payment provider webhook contract": { method: "POST", path: "/api/payments/webhooks/:provider", service: "payment-webhook-worker", monitor: "payment_webhook.worker.verified" },
    "Entitlement unlock service": { method: "POST", path: "/api/entitlements/project", service: "entitlement-worker", monitor: "entitlement.worker.projected" },
    "Support and refund casebook": { method: "POST", path: "/api/support/cases/:case_id/closeout", service: "support-refund-worker", monitor: "support_case.worker.closed" },
    "Account research vault migration": { method: "POST", path: "/api/account-vault/migrations", service: "account-vault-worker", monitor: "account_vault.worker.migrated" },
    "Evidence release and claim freeze": { method: "POST", path: "/api/claims/:claim_id/release-state", service: "claim-release-worker", monitor: "claim_release.worker.frozen_or_released" },
    "Privacy export/delete job": { method: "POST", path: "/api/privacy/requests/:privacy_request_id/run", service: "privacy-job-worker", monitor: "privacy_job.worker.completed" },
    "Founder pilot operations queue": { method: "POST", path: "/api/founder-beta/ops-queue/:queue_id/review", service: "founder-ops-worker", monitor: "founder_ops.worker.reviewed" }
  };
  const closeoutByTitle = Object.fromEntries(closeout.tickets.map((ticket) => [ticket.title, ticket]));
  const endpoints = factory.tickets.map((ticket, index) => {
    const closeoutTicket = closeoutByTitle[ticket.title] || ticket;
    const endpoint = endpointMap[ticket.title] || { method: "POST", path: `/api/workers/${ticket.title.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, service: "worker-endpoint", monitor: "worker.endpoint.accepted" };
    const payloadFields = [...new Set([
      "request_id",
      "idempotency_key",
      "actor_role",
      "ticket_id",
      "closeout_id",
      ...ticket.eventContract,
      "blocked_data_scan",
      "created_at"
    ])];
    const logs = [
      `${endpoint.service}.request_log`,
      `${endpoint.service}.receipt_log`,
      `${endpoint.service}.replay_log`,
      `${endpoint.service}.redaction_log`
    ];
    const monitorFields = [
      "latency_ms",
      "delivery_state",
      "retry_count",
      "dead_letter_state",
      "owner_acknowledged_at"
    ];
    const acceptanceScore = clampNumber(Math.round(
      closeoutTicket.score * 0.42 +
        ticket.score * 0.22 +
        Math.min(payloadFields.length, 12) * 2 +
        ticket.acceptance.length * 4 +
        (ticket.priority === "P0" ? -6 : ticket.priority === "P1" ? 0 : 4)
    ) - closeoutTicket.blockers.length * 2, 18, 96);
    const blockers = [
      ...closeoutTicket.blockers.filter((blocker) => !blocker.startsWith("No active")).slice(0, 3),
      ...(payloadFields.length < 8 ? ["endpoint payload needs required receipt, actor, idempotency, and closeout fields"] : []),
      ...(logs.length < 4 ? ["endpoint needs request, receipt, replay, and redaction logs"] : []),
      ...(ticket.priority === "P0" && acceptanceScore < 82 ? ["P0 endpoint cannot accept release until score reaches 82/100"] : [])
    ];
    const status = blockers.length
      ? "Endpoint blocked"
      : acceptanceScore >= 82
        ? "Endpoint accepted"
        : "Owner acceptance";
    return {
      ...ticket,
      acceptanceScore,
      blockers: blockers.length ? blockers : ["No active endpoint blocker in this preview. Keep real CI, endpoint auth, audit storage, monitor delivery, and owner signoff before production."],
      closeoutId: closeoutTicket.closeoutId,
      endpointAcceptanceId: ["NN", "ENDPOINT", "ACCEPT", String(index + 1).padStart(2, "0"), suffix].join("-").toUpperCase(),
      logs,
      method: endpoint.method,
      monitorEvent: endpoint.monitor,
      monitorFields,
      path: endpoint.path,
      payloadFields,
      service: endpoint.service,
      status,
      tone: status === "Endpoint accepted" ? "ready" : status === "Endpoint blocked" ? "blocked" : "draft"
    };
  });
  const accepted = endpoints.filter((endpoint) => endpoint.status === "Endpoint accepted").length;
  const review = endpoints.filter((endpoint) => endpoint.status === "Owner acceptance").length;
  const blocked = endpoints.filter((endpoint) => endpoint.status === "Endpoint blocked").length;
  const readiness = clampNumber(Math.round(
    endpoints.reduce((sum, endpoint) => sum + endpoint.acceptanceScore, 0) / endpoints.length * 0.72 +
      closeout.readiness * 0.18 +
      factory.score * 0.1
  ) - blocked * 2, 18, 96);
  const status = blocked
    ? "Endpoint acceptance blocked"
    : readiness >= 84
      ? "Endpoint matrix ready"
      : "Endpoint owner review";
  const tone = status === "Endpoint matrix ready" ? "ready" : status === "Endpoint acceptance blocked" ? "blocked" : "draft";
  const metrics = [
    { label: "Endpoint matrix", value: endpointMatrixId, detail: `${accepted} accepted, ${review} owner review, ${blocked} blocked endpoint${endpoints.length === 1 ? "" : "s"}.` },
    { label: "Acceptance batch", value: acceptanceBatchId, detail: `${endpoints.reduce((sum, endpoint) => sum + endpoint.payloadFields.length, 0)} payload fields mapped across ${endpoints.length} workers.` },
    { label: "Monitor handoff", value: monitorHandoffId, detail: "Every endpoint carries request, receipt, replay, redaction, retry, and dead-letter observability." },
    { label: "Release closeout", value: releaseCloseoutId, detail: `${status}; closeout source ${closeout.closeoutId}.` }
  ];
  const handoffs = [
    {
      label: "Request logging",
      owner: "Platform",
      value: "request_id + idempotency_key",
      detail: "Every endpoint writes request metadata before business state changes."
    },
    {
      label: "Receipt persistence",
      owner: "Backend",
      value: "append-only receipt",
      detail: "Endpoint success is not trusted until receipt proof is saved."
    },
    {
      label: "Replay monitor",
      owner: "Release Ops",
      value: "replay + retry",
      detail: "Retry, duplicate, replay, and dead-letter states stay observable."
    },
    {
      label: "Redaction scan",
      owner: "Compliance",
      value: "blocked-data proof",
      detail: "Payloads and logs fail if sensitive investor, payment, or distributor data appears."
    }
  ];
  const releaseSequence = [
    "Freeze endpoint scope and match each ticket to method, path, service, payload, logs, monitor event, and owner.",
    "Run schema tests for request ID, idempotency key, actor role, ticket ID, closeout ID, and event contract fields.",
    "Run replay tests for duplicate webhook, refund reversal, entitlement projection, support repair, migration, evidence freeze, privacy job, and founder queue cases.",
    "Attach request, receipt, replay, redaction, retry, dead-letter, and owner acknowledgement logs to the acceptance batch.",
    "Close only when endpoint matrix, backend ticket closeout, monitoring handoff, redaction proof, and release owner signoff agree."
  ];
  const noGoRules = [
    "No endpoint release if request ID, idempotency key, ticket ID, closeout ID, or actor role is missing.",
    "No endpoint release if request, receipt, replay, redaction, retry, dead-letter, or owner acknowledgement logs are missing.",
    "No P0 endpoint release below 82/100 acceptance score.",
    "No endpoint release if support, refund, entitlement, privacy, evidence, account, or payment state can change from browser-local state.",
    "No endpoint release if PAN, folio, CAS, bank data, UPI, card data, OTP, gateway secrets, contact data, private notes, ARN/EUIN, or distributor client records enter payloads or logs."
  ];
  const receiptFields = [
    "endpoint_matrix_id",
    "endpoint_acceptance_id",
    "acceptance_batch_id",
    "monitor_handoff_id",
    "release_closeout_id",
    "ticket_id",
    "closeout_id",
    "method",
    "path",
    "service",
    "payload_schema_version",
    "request_log_id",
    "receipt_log_id",
    "replay_log_id",
    "redaction_log_id",
    "monitor_event",
    "owner_acknowledgement",
    "blocked_data_scan",
    "released_at"
  ];
  const blockers = blocked
    ? endpoints.filter((endpoint) => endpoint.status === "Endpoint blocked").map((endpoint) => `${endpoint.title}: ${endpoint.blockers[0] || endpoint.status}`)
    : ["No active endpoint acceptance blocker in this preview. Keep production CI, auth, storage, monitoring, and owner signoff outside browser-local state."];
  return {
    accepted,
    acceptanceBatchId,
    blocked,
    blockers,
    endpointMatrixId,
    endpoints,
    handoffs,
    metrics,
    monitorHandoffId,
    noGoRules,
    readiness,
    receiptFields,
    releaseCloseoutId,
    releaseSequence,
    review,
    status,
    tone
  };
}

