function openAccountVaultBlocker() {
  scrollToHash(accountVaultBlueprintConfig().nextBlocker.route || "#account-vault", "smooth", true);
}

function riskClass(risk) {
  return `risk-${risk.toLowerCase().replaceAll(" ", "-")}`;
}

function selectedFund() {
  return FUNDS.find((fund) => fund.id === state.selectedId) || FUNDS[0];
}

function fundSelectButtonMarkup(fund, label = "Inspect") {
  const cleanLabel = String(label || "Inspect").trim();
  const isSelected = cleanLabel.toLowerCase() === "selected";
  const accessibleLabel = isSelected
    ? `Selected fund: ${fund.name}. Open Fund DNA.`
    : `${cleanLabel} ${fund.name} in Fund DNA.`;
  return `<button class="text-button" type="button" data-select-fund="${escapeHtml(fund.id)}" aria-label="${escapeHtml(accessibleLabel)}" title="${escapeHtml(accessibleLabel)}">${escapeHtml(cleanLabel)}</button>`;
}

function fundCompareToggleMarkup(fund, isCompared = false) {
  const accessibleLabel = isCompared
    ? `Remove ${fund.name} from Compare.`
    : `Add ${fund.name} to Compare.`;
  const checked = isCompared ? "checked" : "";
  return `
    <label class="compare-toggle" title="${escapeHtml(accessibleLabel)}">
      <input type="checkbox" data-compare-fund="${escapeHtml(fund.id)}" ${checked} aria-label="${escapeHtml(accessibleLabel)}">
      Compare
    </label>
  `;
}

function fundSearchText(fund) {
  return [
    fund.name,
    fund.category,
    fund.sleeve,
    fund.risk,
    fund.role,
    fund.style,
    ...fund.tags
  ].join(" ").toLowerCase();
}

function fundMatchesSearchTerm(fund, term) {
  const normalized = String(term || "").trim().toLowerCase();
  return !normalized || fundSearchText(fund).includes(normalized);
}

function searchPresetCount(term) {
  return FUNDS.filter((fund) => fundMatchesSearchTerm(fund, term)).length;
}

function renderSearchPresetCounts() {
  qsa("[data-search-preset]").forEach((button) => {
    const label = button.dataset.searchPresetLabel || button.textContent.trim();
    const count = searchPresetCount(button.dataset.searchPreset || "");
    button.dataset.searchPresetLabel = label;
    button.innerHTML = `${escapeHtml(label)} <small>${count}</small>`;
  });
}

function filteredFunds() {
  const term = state.filters.search.trim().toLowerCase();
  const items = FUNDS.filter((fund) => {
    return (
      fundMatchesSearchTerm(fund, term) &&
      (state.filters.category === "all" || fund.category === state.filters.category) &&
      (state.filters.risk === "all" || fund.risk === state.filters.risk)
    );
  });

  return items.sort((a, b) => {
    if (state.filters.sort === "expense") return a.expense - b.expense;
    if (state.filters.sort === "consistency") return b.consistency - a.consistency;
    if (state.filters.sort === "drawdown") return a.maxDrawdown - b.maxDrawdown;
    return nadiScore(b) - nadiScore(a);
  });
}

function simpleAdvancedFilterLabels() {
  const labels = [];
  if (state.filters.category !== "all") labels.push(`Category ${state.filters.category}`);
  if (state.filters.risk !== "all") labels.push(`Risk ${state.filters.risk}`);
  if (state.filters.sort !== "score") {
    const sortLabels = {
      expense: "Lowest expense",
      consistency: "Consistency",
      drawdown: "Drawdown control"
    };
    labels.push(`Sort ${sortLabels[state.filters.sort] || state.filters.sort}`);
  }
  return labels;
}

function syncSimpleFilterToggle() {
  const activeLabels = simpleAdvancedFilterLabels();
  const activeCount = activeLabels.length;
  const activePhrase = activeLabels.join(", ");
  const activeSuffix = activeCount ? ` Active filters: ${activePhrase}.` : "";
  if (els.simpleFilterToggle) {
    const voiceLabel = state.simpleFiltersOpen
      ? `Hide filters and return to one-search Simple View.${activeSuffix}`
      : activeCount
        ? `Show filters. ${activeCount} active ${activeCount === 1 ? "filter" : "filters"}: ${activePhrase}.`
        : "Show category, risk, and sort filters";
    els.simpleFilterToggle.dataset.activeFilters = String(activeCount);
    els.simpleFilterToggle.setAttribute("aria-expanded", state.simpleFiltersOpen ? "true" : "false");
    els.simpleFilterToggle.setAttribute("aria-label", voiceLabel);
    els.simpleFilterToggle.textContent = state.simpleFiltersOpen ? "Quiet search" : activeCount ? `Filters ${activeCount}` : "More filters";
    els.simpleFilterToggle.title = state.simpleFiltersOpen
      ? `Return to one-search Simple View.${activeSuffix}`
      : activeCount
        ? `${activeCount} hidden ${activeCount === 1 ? "filter is" : "filters are"} shaping results: ${activePhrase}`
        : "Show category, risk, and sort filters";
  }
  if (els.simpleFilterReset) {
    const searchSuffix = state.filters.search.trim() ? " and keep the search" : "";
    els.simpleFilterReset.dataset.activeFilters = String(activeCount);
    els.simpleFilterReset.hidden = activeCount === 0;
    els.simpleFilterReset.textContent = "Clear filters";
    els.simpleFilterReset.setAttribute(
      "aria-label",
      activeCount ? `Clear hidden filters${searchSuffix}, close filters, then return to search: ${activePhrase}` : "No hidden filters to clear"
    );
    els.simpleFilterReset.title = activeCount
      ? `Clear ${activeCount} hidden ${activeCount === 1 ? "filter" : "filters"}${searchSuffix}; close filters and return to search`
      : "No hidden filters to clear";
  }
}

function renderCategoryFilter() {
  if (!els.categoryFilter || els.categoryFilter.dataset.hydrated === "true") return;
  const categories = [...new Set(FUNDS.map((fund) => fund.category))].sort();
  els.categoryFilter.insertAdjacentHTML(
    "beforeend",
    categories.map((category) => `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join("")
  );
  els.categoryFilter.dataset.hydrated = "true";
}

function renderWatchFundSelect() {
  if (!els.watchFundSelect) return;
  els.watchFundSelect.innerHTML = FUNDS.map((fund) => `
    <option value="${escapeHtml(fund.id)}">${escapeHtml(fund.name)} | ${escapeHtml(fund.category)}</option>
  `).join("");
  els.watchFundSelect.value = state.selectedId;
}

function renderFundGrid() {
  syncSimpleFilterToggle();
  const funds = filteredFunds();
  const term = state.filters.search.trim();
  const topMatch = funds[0];
  const shelfCanCollapse = state.simpleMode && funds.length > SIMPLE_FUND_SHELF_LIMIT;
  const shelfCollapsed = shelfCanCollapse && !state.simpleFundShelfExpanded;
  const displayFunds = shelfCollapsed ? funds.slice(0, SIMPLE_FUND_SHELF_LIMIT) : funds;
  if (els.fundCount) {
    els.fundCount.textContent = shelfCollapsed
      ? `${displayFunds.length} calm picks of ${funds.length} matches`
      : `${funds.length} of ${FUNDS.length} funds`;
  }
  if (els.searchFeedback) {
    const label = term
      ? `Showing ${funds.length} of ${FUNDS.length} funds for "${escapeHtml(term)}".`
      : `Showing all ${FUNDS.length} demo funds.`;
    const resetReceipt = state.simpleFilterReceipt
      ? `<strong class="search-reset-receipt">${escapeHtml(state.simpleFilterReceipt)}</strong>`
      : "";
    els.searchFeedback.innerHTML = `
      <span>${label}</span>
      ${resetReceipt}
      ${term && topMatch ? `<strong class="search-top-match">Top match: ${escapeHtml(topMatch.name)}</strong>` : ""}
      ${term && topMatch ? `<button class="signal-chip is-primary" type="button" data-open-top-match aria-label="Open top match ${escapeHtml(topMatch.name)}">Open top match</button>` : ""}
      ${term ? '<button class="signal-chip" type="button" data-clear-search>Clear</button>' : ""}
    `;
  }
  if (!funds.length) {
    const hint = term
      ? `No demo fund matches "${escapeHtml(term)}" yet. Clear it or try a starter search.`
      : "No funds match this research filter. Clear filters or try a starter search.";
    els.fundGrid.innerHTML = `
      <div class="no-results search-rescue">
        <strong>No match found</strong>
        <span>${hint}</span>
        <div class="search-rescue-actions" aria-label="Search recovery actions">
          <button class="signal-chip" type="button" data-clear-search>Clear search</button>
          <button class="signal-chip" type="button" data-search-preset="large cap">Large cap</button>
          <button class="signal-chip" type="button" data-search-preset="debt">Debt</button>
          <button class="signal-chip" type="button" data-search-preset="tax saver">Tax saver</button>
        </div>
      </div>
    `;
    renderSearchPresetCounts();
    return;
  }

  const shelfFooter = shelfCanCollapse
    ? `
      <div class="quiet-fund-shelf" role="note">
        <span>${shelfCollapsed ? `Showing the first ${displayFunds.length} calm picks from ${funds.length} matches.` : "Full fund shelf open for this view."}</span>
        <button class="text-button" type="button" data-expand-fund-shelf="${shelfCollapsed ? "true" : "false"}">
          ${shelfCollapsed ? `Show all ${funds.length}` : "Calm shelf"}
        </button>
      </div>
    `
    : "";

  els.fundGrid.innerHTML = displayFunds.map((fund) => {
    const score = nadiScore(fund);
    const selected = fund.id === state.selectedId ? " is-selected" : "";
    const compared = state.compare.has(fund.id);
    const tags = [fund.sleeve, fund.risk]
      .map((tag) => `<span class="tag ${tag === fund.risk ? riskClass(fund.risk) : ""}">${escapeHtml(tag)}</span>`)
      .join("");
    const consistency = Math.min(100, Math.max(0, fund.consistency));
    const drawdown = Math.min(100, Math.max(0, 100 - fund.maxDrawdown * 2));

    return `
      <article class="fund-card${selected}" data-fund-card="${escapeHtml(fund.id)}">
        <div class="fund-card-top">
          <div>
            <div class="fund-meta">${tags}</div>
            <h3>${escapeHtml(fund.name)}</h3>
            <p class="fund-category">${escapeHtml(fund.category)}</p>
          </div>
          <div class="score" style="--score: ${score}"><span>${score}</span></div>
        </div>
        <p class="score-copy">${escapeHtml(fund.role)}</p>
        <div class="signal-strip" aria-label="${escapeHtml(fund.name)} signal strength">
          <div class="signal-row">
            <span>Consistency</span>
            <div class="signal-bar"><span style="width: ${consistency}%"></span></div>
            <strong>${consistency}</strong>
          </div>
          <div class="signal-row">
            <span>Risk control</span>
            <div class="signal-bar"><span style="width: ${drawdown}%"></span></div>
            <strong>${drawdown}</strong>
          </div>
        </div>
        <div class="metric-grid">
          <div><span>Expense</span><strong>${fund.expense.toFixed(2)}%</strong></div>
          <div><span>5Y demo</span><strong>${fund.returns5y.toFixed(1)}%</strong></div>
          <div><span>Drawdown</span><strong>${fund.maxDrawdown}%</strong></div>
        </div>
        <div class="fund-actions">
          ${fundSelectButtonMarkup(fund)}
          ${fundCompareToggleMarkup(fund, compared)}
        </div>
      </article>
    `;
  }).join("") + shelfFooter;
  renderSearchPresetCounts();
}

function readProfileRoomConfig() {
  return {
    confidence: els.profileConfidence?.value || "new",
    drawdown: els.profileDrawdown?.value || "balanced",
    emergency: els.profileEmergency?.value || "partial",
    horizon: clampNumber(Number(els.profileHorizon?.value || 7), 1, 40),
    intent: els.profileIntent?.value || "first-sip",
    sip: clampNumber(Number(els.profileMonthlySip?.value || 10000), 0, 10000000)
  };
}

function profileIntentLabel(intent) {
  return {
    "first-sip": "Start or improve SIP",
    parking: "Park money or STP source",
    tax: "ELSS tax route",
    retirement: "Long-term wealth goal",
    review: "Portfolio review"
  }[intent] || "Start or improve SIP";
}

function profileDrawdownLabel(drawdown) {
  return {
    low: "Low volatility preferred",
    balanced: "Normal equity swings",
    growth: "High volatility accepted",
    aggressive: "Sharp drawdowns accepted"
  }[drawdown] || "Normal equity swings";
}

function profileConfidenceLabel(confidence) {
  return {
    new: "New to mutual funds",
    building: "Building research habit",
    reviewing: "Already reviewing funds"
  }[confidence] || "New to mutual funds";
}

function profileRoomRisk(drawdown) {
  if (drawdown === "low") return "conservative";
  if (drawdown === "growth") return "growth";
  if (drawdown === "aggressive") return "aggressive";
  return "balanced";
}

function profileRoomInvestorConfig(config = readProfileRoomConfig()) {
  return {
    confidence: config.confidence === "reviewing" || config.intent === "review" ? "shortlist" : config.confidence === "building" ? "shortlist" : "exploring",
    emergency: config.emergency,
    goal: config.intent,
    horizon: config.horizon,
    risk: profileRoomRisk(config.drawdown),
    sip: config.sip,
    stage: config.confidence === "new" ? "new" : config.confidence === "reviewing" ? "reviewing" : "building"
  };
}

function profilePrimaryCategory(config, investorConfig) {
  if (config.emergency === "no" || config.intent === "parking" || config.horizon < 3) return "Liquid Fund";
  if (config.intent === "tax") return "ELSS Fund";
  if (config.intent === "retirement" && config.horizon >= 12) return "Life Cycle Fund";
  if (config.intent === "review") return "Index Fund";
  if (investorConfig.risk === "conservative") return "Balanced Hybrid Fund";
  if (investorConfig.risk === "aggressive") return "Flexi Cap Fund";
  return config.horizon >= 7 ? "Large Cap Fund" : "Balanced Hybrid Fund";
}

function profileRoomRoute(config, investorConfig) {
  if (config.intent === "review") return "#portfolio-review";
  if (config.emergency === "no" || config.intent === "parking" || config.intent === "tax") return "#category-playbook";
  if (config.confidence === "reviewing") return "#compare";
  return investorRoute(investorConfig);
}

function profileRoomProfile() {
  const config = readProfileRoomConfig();
  const investorConfig = profileRoomInvestorConfig(config);
  const route = profileRoomRoute(config, investorConfig);
  const primaryCategory = profilePrimaryCategory(config, investorConfig);
  const selected = selectedFund();
  const candidates = FUNDS
    .map((fund) => {
      let score = investorFundFitScore(fund, investorConfig);
      if (fund.category === primaryCategory) score += 10;
      if (config.confidence === "new" && ["Small Cap Fund", "Mid Cap Fund"].includes(fund.category)) score -= 10;
      if (config.drawdown === "aggressive" && ["Mid Cap Fund", "Small Cap Fund", "Flexi Cap Fund"].includes(fund.category)) score += 6;
      return { fund, score: Math.round(clampNumber(score, 18, 98)) };
    })
    .sort((a, b) => b.score - a.score || nadiScore(b.fund) - nadiScore(a.fund));

  const selectedFit = candidates.find((item) => item.fund.id === selected.id)?.score || investorFundFitScore(selected, investorConfig);
  let readiness = 58;
  readiness += config.emergency === "yes" ? 12 : config.emergency === "partial" ? 4 : -18;
  readiness += config.horizon >= 7 ? 9 : config.horizon >= 3 ? 3 : -9;
  readiness += config.sip > 0 ? 5 : -8;
  readiness += config.confidence === "reviewing" ? 7 : config.confidence === "building" ? 4 : 0;
  readiness += config.drawdown === "aggressive" && config.horizon < 7 ? -12 : 0;
  readiness += selectedFit >= 75 ? 4 : selectedFit < 50 ? -6 : 0;
  readiness = Math.round(clampNumber(readiness, 24, 95));

  const posture = (() => {
    if (config.emergency === "no") return "Safety buffer first";
    if (config.horizon < 3) return "Liquidity-first route";
    if (config.intent === "review") return "Review route ready";
    if (config.intent === "tax") return "Tax route framed";
    if (config.drawdown === "aggressive") return "Satellite discipline needed";
    if (config.confidence === "new") return "Starter route ready";
    return "Research route ready";
  })();
  const tone = readiness >= 74 ? "strong" : readiness >= 56 ? "watch" : "caution";
  const categoryRoute = (() => {
    if (config.emergency === "no") return "Emergency buffer and liquid/debt research should come before volatile fund selection.";
    if (config.intent === "parking") return "Cash parking, STP source, liquid fund, and debt quality checks come first.";
    if (config.intent === "tax") return "ELSS can be studied, but tax benefit must be separated from investment fit.";
    if (config.intent === "retirement") return "Long-horizon route should compare core equity, passive, hybrid, and glide-path options.";
    if (config.intent === "review") return "Review starts with X-Ray, compare, cost, evidence, and role duplication checks.";
    return "Starter SIP route should compare simple core categories before satellite risk.";
  })();
  const guardrails = [
    "No PAN, folio, CAS file, bank detail, account credential, or personal identifier is needed for this profile.",
    "The profile only routes research workflow; it is not suitability approval, advice, execution, or a return guarantee.",
    "Before launch use, connect live AMFI, AMC factsheet, SID/KIM, TER, riskometer, and portfolio disclosure sources."
  ];
  if (config.emergency === "no") guardrails.push("Do not frame equity SIP research as urgent until emergency money is protected.");
  if (config.drawdown === "aggressive") guardrails.push("Aggressive drawdown comfort still needs sizing, core allocation, and stress testing.");
  if (config.horizon < 5 && ["growth", "aggressive"].includes(investorConfig.risk)) guardrails.push("High volatility with a short horizon needs a written pause rule.");

  return {
    amountLabel: formatMoney(config.sip),
    candidates,
    categoryRoute,
    config,
    guardrails,
    investorConfig,
    posture,
    primaryCategory,
    readiness,
    route,
    routeLabel: workspaceOption(route)?.textContent?.trim() || "Research route",
    selected,
    selectedFit,
    tone
  };
}

function profileInvestorTwin(profile) {
  const config = profile.config;
  const fund = profile.selected;
  const evidence = evidenceReadinessScore(fund);
  const nadi = nadiScore(fund);
  const suffix = DATA_VERSION.replace(/-/g, "");
  const twinId = ["NN", "INVESTOR", "TWIN", suffix, config.intent, profile.primaryCategory.replace(/[^a-z0-9]+/gi, "-")].join("-").toUpperCase();
  const emergencyScore = config.emergency === "yes" ? 88 : config.emergency === "partial" ? 66 : 30;
  const horizonScore = config.horizon >= 10 ? 88 : config.horizon >= 7 ? 78 : config.horizon >= 3 ? 58 : 34;
  const sipScore = config.sip >= 5000 ? 78 : config.sip > 0 ? 58 : 28;
  const drawdownScore = {
    low: fund.maxDrawdown <= 10 ? 82 : 46,
    balanced: fund.maxDrawdown <= 18 ? 76 : 58,
    growth: fund.maxDrawdown <= 25 ? 74 : 62,
    aggressive: fund.maxDrawdown <= 35 ? 72 : 54
  }[config.drawdown] || 62;
  const confidenceScore = config.confidence === "reviewing" ? 84 : config.confidence === "building" ? 70 : 54;
  const scenarioTemplates = [
    {
      label: "SIP boredom twin",
      trigger: "Twelve quiet months with no exciting headline return.",
      route: "#journey-timeline",
      trap: "stopping the process because the result feels slow",
      rehearsal: "review the route, memo, and calendar before changing SIP behavior",
      weight: [sipScore, confidenceScore, horizonScore]
    },
    {
      label: "Drawdown panic twin",
      trigger: `${fund.maxDrawdown}% demo drawdown appears on the selected fund.`,
      route: "#stress-lab",
      trap: "switching after pain without checking role, horizon, and written reason",
      rehearsal: "run stress impact, pause rule, compare set, and decision memo first",
      weight: [drawdownScore, horizonScore, profile.readiness]
    },
    {
      label: "Emergency shock twin",
      trigger: "Unexpected cash need arrives while the research route is active.",
      route: "#category-playbook",
      trap: "treating volatile money as emergency money",
      rehearsal: "separate emergency buffer, parking bucket, and long-horizon research",
      weight: [emergencyScore, sipScore, profile.readiness]
    },
    {
      label: "Return-chasing twin",
      trigger: "A high-return fund, friend tip, or social post looks more exciting.",
      route: "#behavior-guard",
      trap: "borrowing conviction before source evidence and role fit",
      rehearsal: "convert the claim into evidence, peer benchmark, and own-word reason",
      weight: [confidenceScore, evidence, nadi]
    },
    {
      label: "Goal-drift twin",
      trigger: "The stated horizon changes from long-term investing to near-term use.",
      route: "#goal-fit",
      trap: "keeping the same fund role after the money purpose changed",
      rehearsal: "re-run goal fit, category route, liquidity need, and horizon band",
      weight: [horizonScore, profile.selectedFit, emergencyScore]
    },
    {
      label: "Evidence-gap twin",
      trigger: "Source date, factsheet, TER, riskometer, or portfolio disclosure is missing.",
      route: "#evidence",
      trap: "treating demo or stale research as live conviction",
      rehearsal: "open Evidence Ledger, Citation Binder, and Review route before action",
      weight: [evidence, profile.readiness, confidenceScore]
    },
    {
      label: "Switch temptation twin",
      trigger: "The current fund looks weaker than a peer for a short period.",
      route: "#switch-lab",
      trap: "switching the whole route without checking tax, cost, role, and overlap",
      rehearsal: "use Switch Lab, Compare, Cost Reality, and X-Ray before deciding",
      weight: [profile.selectedFit, nadi, confidenceScore]
    },
    {
      label: "Review fatigue twin",
      trigger: "The investor stops reviewing after the first memo is saved.",
      route: "#review-rhythm",
      trap: "turning a one-time screen into a long-term decision",
      rehearsal: "set 30/60/90-day review rhythm and translate review drift into rupee terms",
      weight: [confidenceScore, profile.readiness, nadi]
    }
  ];
  const scenarios = scenarioTemplates.map((scenario, index) => {
    const base = Math.round(scenario.weight.reduce((sum, value) => sum + value, 0) / scenario.weight.length);
    const score = clampNumber(base - (index % 3) * 2 + (profile.selectedFit >= 78 ? 3 : 0), 18, 96);
    return {
      ...scenario,
      score,
      tone: score >= 76 ? "ready" : score >= 58 ? "watch" : "caution",
      outcome: score >= 76 ? "Future self steady" : score >= 58 ? "Needs a pause rule" : "Behavior blocker"
    };
  });
  const weakest = [...scenarios].sort((a, b) => a.score - b.score)[0];
  const survivalScore = clampNumber(Math.round(
    profile.readiness * 0.24 +
    profile.selectedFit * 0.18 +
    evidence * 0.14 +
    emergencyScore * 0.14 +
    horizonScore * 0.12 +
    confidenceScore * 0.1 +
    drawdownScore * 0.08
  ), 18, 96);
  const posture = survivalScore >= 80 && weakest.score >= 60
    ? "Future-self route ready"
    : survivalScore >= 62
      ? "Future-self rehearsal"
      : "Future-self blocker";
  const tone = posture === "Future-self route ready" ? "strong" : posture === "Future-self blocker" ? "caution" : "watch";
  const metrics = [
    {
      label: "Twin ID",
      value: twinId,
      detail: "Identity-light behavior simulation for this profile route."
    },
    {
      label: "Survival score",
      value: `${survivalScore}/100`,
      detail: "Combines profile readiness, selected fund fit, evidence, emergency buffer, horizon, and behavior comfort."
    },
    {
      label: "Weakest future moment",
      value: weakest.label,
      detail: `${weakest.score}/100 | ${weakest.trap}`
    },
    {
      label: "Next rehearsal",
      value: workspaceOption(weakest.route)?.textContent?.trim() || weakest.route,
      detail: weakest.rehearsal
    }
  ];
  const decisionScript = [
    `I am researching ${fund.name} for ${profileIntentLabel(config.intent).toLowerCase()}, not buying it because of noise.`,
    `My time horizon is ${config.horizon} years and my monthly SIP comfort is ${profile.amountLabel}.`,
    `If ${weakest.trigger.toLowerCase()}, I will open ${workspaceOption(weakest.route)?.textContent?.trim() || weakest.route} before changing the plan.`,
    "I will not use this profile as advice, execution, return promise, or suitability approval."
  ];
  const noGoTriggers = [
    "Emergency buffer is not ready and the fund role is volatile.",
    "The selected fund has missing evidence, stale source date, or unclear riskometer/factsheet posture.",
    "The reason cannot be written in the investor's own words.",
    "The action is driven by social proof, recent return, tax urgency, or fear after drawdown.",
    "The route has no review date, watch trigger, or pause rule."
  ];
  const twinReceipts = [
    "profile_twin_id",
    "intent",
    "horizon_years",
    "sip_comfort",
    "drawdown_comfort",
    "emergency_buffer",
    "selected_fund_id",
    "weakest_scenario",
    "pause_rule",
    "next_route",
    "created_at"
  ];
  return {
    decisionScript,
    metrics,
    noGoTriggers,
    posture,
    scenarios,
    survivalScore,
    tone,
    twinId,
    twinReceipts,
    weakest
  };
}

