function targetFromHash(hash) {
  if (!hash || hash === "#") return null;
  try {
    return document.getElementById(decodeURIComponent(hash.slice(1)));
  } catch {
    return null;
  }
}

function syncWorkspaceFocusClass(hash = window.location.hash) {
  const investorRecordFocus = hash === "#investor-record";
  const simpleRoomFocus = SIMPLE_ROOM_FOCUS_CLASS_BY_HASH.get(hash) || "";
  state.investorRecordFocus = investorRecordFocus;
  state.simpleRoomFocus = simpleRoomFocus;
  document.body.classList.toggle("investor-record-focus", investorRecordFocus);
  document.body.classList.toggle("simple-room-focus", Boolean(simpleRoomFocus));
  document.body.classList.toggle("calm-focus-mode", Boolean(simpleRoomFocus));
  SIMPLE_ROOM_FOCUS_CLASSES.forEach((className) => {
    document.body.classList.toggle(className, className === simpleRoomFocus);
  });
}

function buildWorkspaceOptionIndex() {
  if (!els.workspaceJump || state.workspaceJumpFullHtml) return;
  state.workspaceJumpFullHtml = els.workspaceJump.innerHTML;
  state.workspaceOptionIndex = new Map(
    Array.from(els.workspaceJump.options)
      .filter((option) => option.value)
      .map((option) => [
        option.value,
        {
          label: option.textContent.trim(),
          group: option.parentElement?.tagName === "OPTGROUP" ? option.parentElement.label : "Workspace"
        }
      ])
  );
}

function renderWorkspaceJumpForMode(activeHash = window.location.hash) {
  if (!els.workspaceJump) return;
  if (!state.workspaceJumpFullHtml) buildWorkspaceOptionIndex();
  if (!state.simpleMode) {
    if (state.workspaceJumpFullHtml && els.workspaceJump.innerHTML !== state.workspaceJumpFullHtml) {
      els.workspaceJump.innerHTML = state.workspaceJumpFullHtml;
    }
    return;
  }

  const pathRoutes = SIMPLE_WORKSPACE_ROUTES.slice(0, 5);
  const optionalRoutes = SIMPLE_WORKSPACE_ROUTES.slice(5);
  const groups = [
    { label: "Simple path", routes: pathRoutes },
    { label: "Optional", routes: optionalRoutes }
  ];

  if (activeHash && targetFromHash(activeHash) && !SIMPLE_WORKSPACE_ROUTE_SET.has(activeHash)) {
    const meta = state.workspaceOptionIndex.get(activeHash);
    groups.unshift({
      label: "Current deep link",
      routes: [{ label: meta?.label || "Current workspace", value: activeHash }]
    });
  }

  els.workspaceJump.innerHTML = [
    '<option value="">Guided steps</option>',
    ...groups.map((group) => (
      `<optgroup label="${escapeHtml(group.label)}">` +
      group.routes.map((route) => `<option value="${escapeHtml(route.value)}">${escapeHtml(route.label)}</option>`).join("") +
      "</optgroup>"
    )),
    '<optgroup label="Full workshop"><option value="" disabled>Switch to Full view for every tool</option></optgroup>'
  ].join("");
}

function stickyHeaderOffset() {
  const header = document.querySelector(".app-header");
  if (!header) return 14;
  const headerStyle = window.getComputedStyle(header);
  if (headerStyle.position !== "sticky" && headerStyle.position !== "fixed") return 14;
  const landingGap = document.body.classList.contains("simple-mode") ? 10 : 28;
  return Math.ceil(header.getBoundingClientRect().height) + landingGap;
}

function syncDeskRailHeroClearance() {
  const header = qs(".app-header");
  if (!header) {
    document.documentElement.style.removeProperty("--desk-rail-top");
    return;
  }
  const headerStyle = window.getComputedStyle(header);
  const headerIsPinned = headerStyle.position === "sticky" || headerStyle.position === "fixed";
  const railTop = headerIsPinned ? Math.max(0, Math.ceil(header.getBoundingClientRect().bottom)) : 0;
  document.documentElement.style.setProperty("--desk-rail-top", `${railTop}px`);
}

function bindDeskRailHeroClearance() {
  syncDeskRailHeroClearance();
  window.addEventListener("resize", syncDeskRailHeroClearance);
  if (deskRailHeroClearanceObserver || !("ResizeObserver" in window)) return;
  const header = qs(".app-header");
  if (!header) return;
  deskRailHeroClearanceObserver = new ResizeObserver(syncDeskRailHeroClearance);
  deskRailHeroClearanceObserver.observe(header);
}

function scrollToElement(element, behavior = "smooth") {
  if (!element) return;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const top = Math.max(0, element.getBoundingClientRect().top + window.scrollY - stickyHeaderOffset());
  window.scrollTo({ top, behavior: reduceMotion ? "auto" : behavior });
}

function workspaceFocusTarget(hash = "") {
  const target = targetFromHash(hash);
  if (!target) return null;
  return target.querySelector("h2, h3, [data-room-title]") || target;
}

function queueWorkspaceFocusHandoff(hash = "", delay = 180) {
  if (!hash || !targetFromHash(hash)) return;
  if (state.workspaceFocusTimer) window.clearTimeout(state.workspaceFocusTimer);
  state.workspaceFocusTimer = window.setTimeout(() => {
    state.workspaceFocusTimer = 0;
    const target = targetFromHash(hash);
    const focusTarget = workspaceFocusTarget(hash);
    if (!target || !focusTarget || !focusTarget.getClientRects().length) return;
    if (target.contains(document.activeElement)) return;
    if (!focusTarget.hasAttribute("tabindex")) {
      focusTarget.setAttribute("tabindex", "-1");
    }
    focusTarget.dataset.quietFocusTarget = "true";
    try {
      focusTarget.focus({ preventScroll: true });
    } catch (error) {
      focusTarget.focus();
    }
    state.workspaceFocusedHash = hash;
  }, Math.max(0, delay));
}

function landBuildProgressRoadmap(behavior = "auto") {
  const title = qs("#build-progress-roadmap-title");
  if (!title) return;
  const header = qs(".app-header");
  const headerStyle = header ? window.getComputedStyle(header) : null;
  const headerBottom = header && (headerStyle.position === "sticky" || headerStyle.position === "fixed")
    ? Math.ceil(header.getBoundingClientRect().bottom) + 12
    : 20;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const top = Math.max(0, window.scrollY + title.getBoundingClientRect().top - headerBottom);
  window.scrollTo({ top, behavior: reduceMotion ? "auto" : behavior });
}

function isElementLanded(element) {
  if (!element) return false;
  const top = element.getBoundingClientRect().top;
  const offset = stickyHeaderOffset();
  return Math.abs(top - offset) <= HASH_LANDING_TOLERANCE || (top >= offset && top <= offset + HASH_LANDING_TOLERANCE * 2);
}

function lockHashLanding(hash, behavior = "auto") {
  const target = targetFromHash(hash);
  if (!target) return;
  if (!isElementLanded(target)) {
    scrollToElement(target, behavior);
  }
}

function scrollToHash(hash, behavior = "smooth", updateHash = false) {
  const target = targetFromHash(hash);
  if (!target) return;
  state.hashSettleUntil = Date.now() + HASH_SETTLE_WINDOW;
  syncWorkspaceFocusClass(hash);
  renderWorkspaceJumpForMode(hash);
  updateWorkspaceNavigator(hash);
  scrollToElement(target, behavior);
  queueWorkspaceFocusHandoff(hash, behavior === "smooth" ? 260 : 80);
  if (updateHash && window.location.hash !== hash) {
    window.history.pushState(null, "", hash);
  }
  window.setTimeout(() => {
    if (window.location.hash === hash) lockHashLanding(hash, "auto");
  }, 180);
}

function settleHashNavigation() {
  const hash = window.location.hash;
  syncWorkspaceFocusClass(hash);
  if (!targetFromHash(hash)) return;
  state.hashSettleUntil = Date.now() + HASH_SETTLE_WINDOW;
  renderWorkspaceJumpForMode(hash);
  updateWorkspaceNavigator(hash);
  requestAnimationFrame(() => {
    updateWorkspaceNavigator(hash);
    if (hash === "#build-progress-roadmap") landBuildProgressRoadmap("auto");
    else lockHashLanding(hash, "auto");
    requestAnimationFrame(() => {
      if (window.location.hash !== hash) return;
      updateWorkspaceNavigator(hash);
      if (hash === "#build-progress-roadmap") landBuildProgressRoadmap("auto");
      else lockHashLanding(hash, "auto");
    });
  });
  HASH_SETTLE_DELAYS.forEach((delay) => {
    window.setTimeout(() => {
      if (window.location.hash !== hash) return;
      updateWorkspaceNavigator(hash);
      if (hash === "#build-progress-roadmap") landBuildProgressRoadmap("auto");
      else lockHashLanding(hash, "auto");
    }, delay);
  });
  if (hash === "#build-progress-roadmap") {
    [0, 220, 520].forEach((delay) => {
      window.setTimeout(() => {
        if (window.location.hash === "#build-progress-roadmap") landBuildProgressRoadmap("auto");
      }, delay);
    });
  }
  window.setTimeout(() => {
    updateWorkspaceNavigator(hash);
  }, HASH_SETTLE_WINDOW + 100);
}

function workspaceOption(hash) {
  if (!els.workspaceJump || !hash) return null;
  const option = Array.from(els.workspaceJump.options).find((entry) => entry.value === hash);
  if (option) return option;
  const meta = state.workspaceOptionIndex.get(hash);
  if (!meta) return null;
  return {
    value: hash,
    textContent: meta.label,
    parentElement: { tagName: "OPTGROUP", label: meta.group }
  };
}

function workspaceHashFromViewport() {
  const sections = qsa(".workspace-band[id]").filter((section) => section.getClientRects().length);
  if (!sections.length) return "#screener";
  const offset = stickyHeaderOffset() + (document.body.classList.contains("simple-mode") ? 12 : 28);
  let active = sections[0];
  for (const section of sections) {
    if (section.getBoundingClientRect().top <= offset) {
      active = section;
    } else {
      break;
    }
  }
  return `#${active.id}`;
}

const RAIL_CONTEXT_GROUP_ROUTES = {
  "Guided path": "#profile-room",
  "Quick routes": "#screener",
  Discover: "#screener",
  "Compare and Fit": "#compare",
  Portfolio: "#portfolio",
  "Trust and Follow-up": "#evidence"
};

const RAIL_GROUP_ALIASES = {
  "Guided path": "Desk",
  "Quick routes": "Desk",
  Discover: "Desk",
  "Compare and Fit": "Research",
  Portfolio: "Research",
  "Trust and Follow-up": "Trust",
  Workspace: "Desk"
};

const RAIL_GROUP_FALLBACK_ROUTES = {
  Desk: "#build-tracker",
  Research: "#compare",
  Trust: "#launch-readiness",
  Founder: "#founder-beta-operating-room"
};

function railMetaFromLink(link) {
  const hash = link?.getAttribute("href") || "";
  const label = link?.querySelector("strong")?.textContent?.trim() || link?.textContent?.trim() || "Workspace";
  const groupNode = link?.closest(".desk-rail-group");
  const group = groupNode?.dataset?.railGroupName || groupNode?.querySelector(".desk-rail-label")?.textContent?.trim() || "Workspace";
  return { hash, label, group };
}

function railGroupLabel(group = "") {
  return RAIL_GROUP_ALIASES[group] || group || "Desk";
}

function railFallbackRouteForGroup(groupLabel = "Desk") {
  return RAIL_GROUP_FALLBACK_ROUTES[groupLabel] || RAIL_GROUP_FALLBACK_ROUTES.Desk;
}

function railLabelForHash(hash = "") {
  const railLink = qsa(".desk-rail a[href^='#']").find((link) => link.getAttribute("href") === hash);
  if (railLink) return railMetaFromLink(railLink).label;
  return workspaceOption(hash)?.textContent?.trim() || "workspace";
}

function loadRailGroupMemory() {
  if (state.railGroupMemoryLoaded) return;
  const memory = {};
  Object.entries(RAIL_GROUP_FALLBACK_ROUTES).forEach(([group, fallback]) => {
    memory[group] = fallback;
  });
  try {
    const saved = JSON.parse(localStorage.getItem(RAIL_GROUP_MEMORY_KEY) || "{}");
    Object.entries(RAIL_GROUP_FALLBACK_ROUTES).forEach(([group, fallback]) => {
      const hash = saved?.[group];
      memory[group] = hash && targetFromHash(hash) ? hash : fallback;
    });
  } catch (error) {
    // Rail memory is a comfort setting; fallback routes keep navigation complete.
  }
  state.railGroupMemory = memory;
  state.railGroupMemoryLoaded = true;
}

function saveRailGroupMemory() {
  try {
    localStorage.setItem(RAIL_GROUP_MEMORY_KEY, JSON.stringify(state.railGroupMemory));
  } catch (error) {
    // Group memory is optional; fixed rail routes remain the durable fallback.
  }
}

function railGroupNameFromNode(group) {
  return group?.dataset?.railGroupName || group?.querySelector(".desk-rail-label")?.textContent?.trim() || "";
}

function loadRailCollapseMemory() {
  if (state.railCollapseLoaded) return;
  const defaults = ["Research", "Trust", "Founder"];
  let collapsed = defaults;
  try {
    const saved = JSON.parse(localStorage.getItem(RAIL_COLLAPSE_MEMORY_KEY) || "null");
    if (Array.isArray(saved)) {
      collapsed = saved.filter((group) => RAIL_GROUP_FALLBACK_ROUTES[group]);
    }
  } catch (error) {
    // Collapse memory is optional; default compact groups keep the rail usable.
  }
  state.railCollapsedGroups = new Set(collapsed);
  state.railCollapseLoaded = true;
}

function saveRailCollapseMemory() {
  try {
    localStorage.setItem(RAIL_COLLAPSE_MEMORY_KEY, JSON.stringify(Array.from(state.railCollapsedGroups)));
  } catch (error) {
    // Collapsed groups are a visual preference; navigation still works without storage.
  }
}

function syncDeskRailGroupCounts() {
  qsa(".desk-rail-group").forEach((group) => {
    const count = group.querySelectorAll("a[href^='#']").length;
    const collapseButton = group.querySelector("[data-rail-collapse]");
    const countBadge = collapseButton?.querySelector("[data-rail-count]");
    group.dataset.railCount = String(count);
    if (!collapseButton) return;
    collapseButton.dataset.railCount = String(count);
    if (countBadge) countBadge.textContent = String(count);
  });
}

function syncDeskRailCollapse(activeGroup = "Desk") {
  loadRailCollapseMemory();
  syncDeskRailGroupCounts();
  qsa(".desk-rail-group").forEach((group) => {
    const label = railGroupNameFromNode(group);
    const collapseButton = group.querySelector("[data-rail-collapse]");
    const isCollapsed = Boolean(label && label !== activeGroup && state.railCollapsedGroups.has(label));
    const count = Number(group.dataset.railCount || 0);
    const roomText = count === 1 ? "1 room" : `${count} rooms`;
    group.classList.toggle("is-collapsed", isCollapsed);
    if (!collapseButton) return;
    collapseButton.dataset.railTip = isCollapsed ? `Expand ${label} (${roomText})` : `${label} open (${roomText})`;
    collapseButton.title = isCollapsed ? `Expand ${label} rail group, ${roomText}` : `${label} rail group open, ${roomText}`;
    collapseButton.setAttribute("aria-expanded", isCollapsed ? "false" : "true");
    collapseButton.setAttribute("aria-label", isCollapsed ? `Expand ${label} rail group, ${roomText}` : `${label} rail group is open, ${roomText}`);
  });
}

function toggleDeskRailGroupCollapse(label = "") {
  if (!label || !RAIL_GROUP_FALLBACK_ROUTES[label]) return;
  loadRailCollapseMemory();
  const activeGroup = railContextForHash(window.location.hash || workspaceHashFromViewport())?.activeGroup || "Desk";
  if (label === activeGroup) {
    state.railCollapsedGroups.delete(label);
  } else if (state.railCollapsedGroups.has(label)) {
    state.railCollapsedGroups.delete(label);
  } else {
    state.railCollapsedGroups.add(label);
  }
  saveRailCollapseMemory();
  syncDeskRailCollapse(activeGroup);
}

function railGroupRoute(groupLabel = "Desk") {
  loadRailGroupMemory();
  const fallback = railFallbackRouteForGroup(groupLabel);
  const hash = state.railGroupMemory[groupLabel] || fallback;
  return targetFromHash(hash) ? hash : fallback;
}

function rememberRailGroupRoute(context) {
  if (!context || !RAIL_GROUP_FALLBACK_ROUTES[context.activeGroup] || !targetFromHash(context.active.hash)) return;
  loadRailGroupMemory();
  if (state.railGroupMemory[context.activeGroup] === context.active.hash) return;
  state.railGroupMemory[context.activeGroup] = context.active.hash;
  saveRailGroupMemory();
}

function rememberDeskRailBacktrack(hash = "") {
  if (!hash || !targetFromHash(hash) || hash === state.railCurrentRoute) return;
  if (state.railCurrentRoute && targetFromHash(state.railCurrentRoute)) {
    state.railBackRoute = state.railCurrentRoute;
    rememberDeskRailRecentRoute(state.railCurrentRoute);
  }
  state.railCurrentRoute = hash;
}

function updateDeskRailBacktrack() {
  if (!els.deskRailBack) return;
  const hash = state.railBackRoute && targetFromHash(state.railBackRoute) ? state.railBackRoute : "";
  const label = hash ? railLabelForHash(hash) : "Previous";
  els.deskRailBack.dataset.railBack = hash;
  els.deskRailBack.disabled = !hash;
  els.deskRailBack.dataset.railTip = hash ? `Back: ${label}` : "Back appears after you move";
  els.deskRailBack.title = hash ? `Back to ${label}` : "Back appears after you move to another workspace";
  els.deskRailBack.setAttribute("aria-label", hash ? `Back to previous workspace: ${label}` : "Previous workspace unavailable yet");
  const backLabel = els.deskRailBack.querySelector("b");
  if (backLabel) backLabel.textContent = label;
}

function rememberDeskRailRecentRoute(hash = "") {
  if (!hash || !targetFromHash(hash)) return;
  state.railRecentRoutes = [
    hash,
    ...state.railRecentRoutes.filter((route) => route !== hash)
  ].slice(0, 2);
}

function updateDeskRailRecentRooms() {
  if (!els.deskRailRecent) return;
  Array.from(els.deskRailRecent.querySelectorAll("[data-rail-recent-index]")).forEach((button, index) => {
    const hash = state.railRecentRoutes[index] && targetFromHash(state.railRecentRoutes[index])
      ? state.railRecentRoutes[index]
      : "";
    const label = hash ? railLabelForHash(hash) : `Recent ${index + 1}`;
    button.dataset.railRecent = hash;
    button.disabled = !hash;
    button.title = hash ? `Open recent room: ${label}` : "Recent room appears after you move";
    button.setAttribute("aria-label", hash ? `Open recent rail room: ${label}` : `Recent rail room ${index + 1} unavailable yet`);
    const roomLabel = button.querySelector("b");
    if (roomLabel) roomLabel.textContent = label;
  });
}

function hydrateDeskRailHints() {
  qsa(".desk-rail a[href^='#']").forEach((link) => {
    const meta = railMetaFromLink(link);
    const number = link.querySelector("span")?.textContent?.trim();
    const group = railGroupLabel(meta.group);
    const hint = [number, meta.label].filter(Boolean).join(" ");
    link.dataset.railTip = `${hint} | ${group}`;
    link.title = `${hint} | ${group}`;
    link.setAttribute("aria-label", `${meta.label}, ${group} workspace`);
  });
  qsa("[data-rail-group-label]").forEach((button) => {
    const label = button.dataset.railGroupLabel || button.textContent?.trim() || "Desk";
    button.dataset.railTip = `${label} rail`;
    button.title = `Open ${label} rail`;
    button.setAttribute("aria-label", `Open ${label} rail group`);
  });
}

function railContextForHash(hash = "") {
  const links = qsa(".desk-rail a[href^='#']");
  const metas = links.map(railMetaFromLink).filter((item) => item.hash);
  if (!metas.length) return null;
  const activeIndex = metas.findIndex((item) => item.hash === hash);
  const option = workspaceOption(hash);
  const optionGroup = option?.parentElement?.tagName === "OPTGROUP" ? option.parentElement.label : "Workspace";
  const active = activeIndex >= 0
    ? metas[activeIndex]
    : {
        hash,
        label: option?.textContent?.trim() || "Screener",
        group: optionGroup
      };
  const fallbackHash = RAIL_CONTEXT_GROUP_ROUTES[active.group] || "#build-tracker";
  const fallbackIndex = metas.findIndex((item) => item.hash === fallbackHash);
  const positionIndex = activeIndex >= 0 ? activeIndex : Math.max(fallbackIndex, 0);
  const total = metas.length;
  const position = Math.min(total, Math.max(1, positionIndex + 1));
  const nextIndex = activeIndex >= 0
    ? (activeIndex + 1) % metas.length
    : Math.max(fallbackIndex, 0);
  return {
    active,
    activeGroup: railGroupLabel(active.group),
    next: metas[nextIndex] || metas[0],
    position,
    total,
    progress: total ? Math.round((position / total) * 100) : 0
  };
}

function updateDeskRailSwitcher(activeGroup = "Desk") {
  qsa("[data-rail-group-label]").forEach((button) => {
    const group = button.dataset.railGroupLabel || "Desk";
    const route = railGroupRoute(group);
    const label = railLabelForHash(route);
    const isActive = group === activeGroup;
    button.dataset.railGroup = route;
    button.dataset.railTip = isActive ? `${group}: ${label}` : `Return to ${label}`;
    button.title = isActive ? `${group} rail: ${label}` : `Return to ${label} in ${group}`;
    button.setAttribute("aria-label", isActive ? `${group} rail, currently on ${label}` : `Return to ${label} in ${group} rail`);
    button.setAttribute("aria-pressed", isActive ? "true" : "false");
  });
}

function deskRailGroupForLabel(groupLabel = "Desk") {
  return qsa(".desk-rail-group").find((group) => {
    const label = railGroupNameFromNode(group);
    return label === groupLabel;
  }) || null;
}

function updateDeskRailGroupFocus(activeGroup = "Desk") {
  qsa(".desk-rail-group").forEach((group) => {
    const label = railGroupNameFromNode(group);
    group.classList.toggle("is-current", label === activeGroup);
  });
  syncDeskRailCollapse(activeGroup);
}

function deskRailTargetForContext(context) {
  if (!context) return null;
  const directLink = qsa(".desk-rail a[href^='#']").find((link) => link.getAttribute("href") === context.active.hash);
  return directLink && directLink.getClientRects().length ? directLink : deskRailGroupForLabel(context.activeGroup);
}

function keepDeskRailTargetVisible(target) {
  if (!els.deskRail || !target || !target.getClientRects().length || window.innerWidth <= 980) return;
  const railRect = els.deskRail.getBoundingClientRect();
  const targetRect = target.getBoundingClientRect();
  const topBuffer = 12;
  const bottomBuffer = 18;
  if (targetRect.top < railRect.top + topBuffer) {
    els.deskRail.scrollTop -= railRect.top + topBuffer - targetRect.top;
  } else if (targetRect.bottom > railRect.bottom - bottomBuffer) {
    els.deskRail.scrollTop += targetRect.bottom - (railRect.bottom - bottomBuffer);
  }
}

function queueDeskRailTargetKeep(target) {
  if (!target || window.innerWidth <= 980) return;
  if (state.railKeepFrame) window.cancelAnimationFrame(state.railKeepFrame);
  state.railKeepFrame = window.requestAnimationFrame(() => {
    state.railKeepFrame = 0;
    keepDeskRailTargetVisible(target);
  });
}

function deskRailFocusableItems() {
  if (!els.deskRail) return [];
  return Array.from(els.deskRail.querySelectorAll("a[href^='#'], button"))
    .filter((item) => !item.disabled && item.getClientRects().length && item.tabIndex !== -1);
}

function focusDeskRailItem(item) {
  if (!item) return;
  item.focus({ preventScroll: true });
  queueDeskRailTargetKeep(item);
}

function moveDeskRailFocus(event) {
  if (!els.deskRail || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  const keyMoves = {
    ArrowDown: 1,
    ArrowRight: 1,
    ArrowUp: -1,
    ArrowLeft: -1
  };
  const isHome = event.key === "Home";
  const isEnd = event.key === "End";
  const delta = keyMoves[event.key];
  if (!delta && !isHome && !isEnd) return;

  const items = deskRailFocusableItems();
  if (!items.length) return;
  event.preventDefault();
  const activeIndex = items.indexOf(document.activeElement);
  const currentIndex = activeIndex >= 0 ? activeIndex : 0;
  const nextIndex = isHome
    ? 0
    : isEnd
      ? items.length - 1
      : (currentIndex + delta + items.length) % items.length;
  focusDeskRailItem(items[nextIndex]);
}

function bindDeskRailKeyboard() {
  if (!els.deskRail) return;
  els.deskRail.dataset.railKeyTravel = "ready";
  els.deskRail.addEventListener("keydown", moveDeskRailFocus);
}

function updateDeskRailContext(hash = "") {
  if (!els.deskRailCurrent || !els.deskRailGroup || !els.deskRailNext) return;
  const context = railContextForHash(hash || workspaceHashFromViewport());
  if (!context) return;
  els.deskRailCurrent.textContent = context.active.label;
  els.deskRailGroup.textContent = context.active.group;
  if (els.deskRailPosition) {
    els.deskRailPosition.textContent = `${String(context.position).padStart(2, "0")}/${context.total}`;
    els.deskRailPosition.title = `${context.active.label} is rail shortcut ${context.position} of ${context.total}`;
  }
  if (els.deskRailProgressBar) {
    els.deskRailProgressBar.style.width = `${context.progress}%`;
  }
  rememberRailGroupRoute(context);
  rememberDeskRailBacktrack(context.active.hash);
  updateDeskRailBacktrack();
  updateDeskRailRecentRooms();
  els.deskRailNext.dataset.railNext = context.next.hash;
  els.deskRailNext.dataset.railTip = `Next: ${context.next.label}`;
  els.deskRailNext.title = `Open ${context.next.label}`;
  els.deskRailNext.setAttribute("aria-label", `Open next workspace: ${context.next.label}`);
  const nextLabel = els.deskRailNext.querySelector("b");
  if (nextLabel) nextLabel.textContent = context.next.label;
  updateDeskRailSwitcher(context.activeGroup);
  updateDeskRailGroupFocus(context.activeGroup);
  queueDeskRailTargetKeep(deskRailTargetForContext(context));
}

function workspaceContext(hash = "") {
  if (hash === "#why-lens") {
    return { label: "Selected fund", value: selectedFund()?.name || "" };
  }
  if (hash === "#compare") {
    const count = state.compare.size;
    return { label: "Compare set", value: `${count} fund${count === 1 ? "" : "s"} in Compare` };
  }
  return { label: "", value: "" };
}

function updateWorkspaceAwareness(hash = "", group = "Workspace", label = "Screener") {
  const cleanLabel = String(label || "Screener").trim();
  const cleanGroup = String(group || "Workspace").trim();
  if (!cleanLabel) return;
  const context = workspaceContext(hash);
  const pageTitle = context.value
    ? `${context.value} | ${cleanLabel} | NiveshNadi Mutual Fund Desk`
    : `${cleanLabel} | NiveshNadi Mutual Fund Desk`;
  if (document.title !== pageTitle) document.title = pageTitle;
  if (!els.workspaceAnnouncer) return;
  if (
    state.workspaceAnnouncedHash === hash &&
    state.workspaceAnnouncedLabel === cleanLabel &&
    state.workspaceAnnouncedContextLabel === context.label &&
    state.workspaceAnnouncedContextValue === context.value
  ) return;
  state.workspaceAnnouncedHash = hash;
  state.workspaceAnnouncedLabel = cleanLabel;
  state.workspaceAnnouncedContextLabel = context.label;
  state.workspaceAnnouncedContextValue = context.value;
  els.workspaceAnnouncer.textContent = context.value
    ? `Current workspace: ${cleanGroup}, ${cleanLabel}. ${context.label}: ${context.value}.`
    : `Current workspace: ${cleanGroup}, ${cleanLabel}.`;
}

function announceSelectedFundReceipt(fund) {
  if (!els.workspaceAnnouncer || !fund?.name) return;
  window.clearTimeout(state.selectedFundReceiptTimer);
  state.selectedFundReceiptTimer = window.setTimeout(() => {
    if (!els.workspaceAnnouncer) return;
    els.workspaceAnnouncer.textContent = `Selected fund: ${fund.name}. Fund DNA opened.`;
  }, 320);
}

function announceCompareSetReceipt(fund, isAdded) {
  if (!els.workspaceAnnouncer || !fund?.name) return;
  window.clearTimeout(state.compareReceiptTimer);
  const count = state.compare.size;
  const countCopy = `${count} fund${count === 1 ? "" : "s"} in Compare.`;
  const actionCopy = isAdded ? "added to Compare" : "removed from Compare";
  state.compareReceiptTimer = window.setTimeout(() => {
    if (!els.workspaceAnnouncer) return;
    els.workspaceAnnouncer.textContent = `${fund.name} ${actionCopy}. ${countCopy}`;
  }, 320);
}

function queueCompareControlFocus(id, source = "compare") {
  if (!id) return;
  if (state.compareFocusFrame) window.cancelAnimationFrame(state.compareFocusFrame);
  state.compareFocusFrame = window.requestAnimationFrame(() => {
    state.compareFocusFrame = 0;
    const attribute = source === "portfolio" ? "data-portfolio-fund" : "data-compare-fund";
    const safeId = String(id).replaceAll("\\", "\\\\").replaceAll('"', '\\"');
    const control = qs(`[${attribute}="${safeId}"]`);
    if (!control || !control.getClientRects().length) return;
    try {
      control.focus({ preventScroll: true });
    } catch (error) {
      control.focus();
    }
  });
}

function updateWorkspaceNavigator(hash = "") {
  renderWorkspaceJumpForMode(hash || workspaceHashFromViewport());
  const fallbackHash = hash && workspaceOption(hash) ? hash : workspaceHashFromViewport();
  const option = workspaceOption(fallbackHash);
  const activeHash = option ? fallbackHash : "";
  renderSimplicityPath(signalStripConfig(), activeHash || fallbackHash);
  if (els.workspaceJump) {
    els.workspaceJump.value = activeHash;
  }
  const group = option?.parentElement?.tagName === "OPTGROUP" ? option.parentElement.label : "Workspace";
  const label = option?.textContent?.trim() || "Screener";
  if (els.workspaceStatus) {
    els.workspaceStatus.textContent = `${group}: ${label}`;
    els.workspaceStatus.title = `Current workspace: ${label}`;
  }
  updateWorkspaceAwareness(activeHash || fallbackHash, group, label);
  if (els.navLinks) {
    els.navLinks.forEach((link) => {
      const isActive = link.getAttribute("href") === activeHash;
      if (isActive) link.setAttribute("aria-current", "page");
      else link.removeAttribute("aria-current");
    });
  }
  updateDeskRailContext(activeHash || fallbackHash);
}

function refreshCompareWorkspaceContext() {
  const activeHash = window.location.hash || workspaceHashFromViewport();
  if (activeHash !== "#compare") return;
  updateWorkspaceNavigator("#compare");
}

function normalizeToolSearch(value = "") {
  return String(value).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function workspaceOptionList() {
  if (!state.workspaceOptionIndex.size) buildWorkspaceOptionIndex();
  const options = new Map();
  const pushOption = (value, label, group, priority = 9) => {
    if (!value || options.has(value) && options.get(value).priority <= priority) return;
    options.set(value, { value, label, group, priority });
  };
  SIMPLE_WORKSPACE_ROUTES.forEach((route, index) => {
    pushOption(route.value, route.label, index < 5 ? "Guided path" : "Quick routes", index);
  });
  state.workspaceOptionIndex.forEach((meta, value) => {
    pushOption(value, meta.label, meta.group || "Workspace", 10);
  });
  return Array.from(options.values());
}

function toolPaletteMatches(query = "") {
  const normalized = normalizeToolSearch(query);
  const options = workspaceOptionList();
  if (!normalized) {
    const defaultRoutes = [
      ...SIMPLE_WORKSPACE_ROUTES.map((route) => route.value),
      "#compare",
      "#portfolio",
      "#research-dossier",
      "#pricing",
      "#build-tracker"
    ];
    const byRoute = new Map(options.map((option) => [option.value, option]));
    return defaultRoutes.map((route) => byRoute.get(route)).filter(Boolean).slice(0, 10);
  }
  const terms = normalized.split(/\s+/).filter(Boolean);
  return options
    .map((option) => {
      const label = normalizeToolSearch(option.label);
      const group = normalizeToolSearch(option.group);
      const route = normalizeToolSearch(option.value.replace(/^#/, ""));
      const haystack = `${label} ${group} ${route}`;
      if (!terms.every((term) => haystack.includes(term))) return null;
      let score = 20;
      if (label === normalized) score = 0;
      else if (label.startsWith(normalized)) score = 1;
      else if (route.startsWith(normalized)) score = 2;
      else if (group.startsWith(normalized)) score = 3;
      else score = 5 + terms.reduce((sum, term) => sum + haystack.indexOf(term), 0);
      return { ...option, score };
    })
    .filter(Boolean)
    .sort((a, b) => a.score - b.score || a.priority - b.priority || a.label.localeCompare(b.label))
    .slice(0, 12);
}

function renderToolPaletteResults(query = els.toolPaletteSearch?.value || "") {
  if (!els.toolPaletteResults) return;
  const matches = toolPaletteMatches(query);
  if (!matches.length) {
    els.toolPaletteResults.innerHTML = `
      <p class="tool-palette-empty">No workspace match. Try evidence, pack, pricing, X-Ray, or account.</p>
    `;
    return;
  }
  els.toolPaletteResults.innerHTML = matches.map((item, index) => `
    <button
      type="button"
      class="tool-palette-result"
      data-tool-palette-route="${escapeHtml(item.value)}"
      role="option"
      aria-selected="${index === 0 ? "true" : "false"}"
    >
      <span>
        <strong>${escapeHtml(item.label)}</strong>
        <small>${escapeHtml(item.group)} | ${escapeHtml(item.value.replace(/^#/, ""))}</small>
      </span>
      <em>Open</em>
    </button>
  `).join("");
}

function openToolPalette() {
  if (!els.toolPalette || !els.toolPaletteToggle || !els.toolPaletteSearch) return;
  state.toolPaletteHost ||= els.toolPalette.parentElement;
  if (window.innerWidth <= 680 && els.toolPalette.parentElement !== document.body) {
    document.body.appendChild(els.toolPalette);
  } else if (window.innerWidth > 680 && state.toolPaletteHost && els.toolPalette.parentElement !== state.toolPaletteHost) {
    state.toolPaletteHost.insertBefore(els.toolPalette, els.workspaceJump || null);
  }
  renderToolPaletteResults();
  els.toolPalette.hidden = false;
  els.toolPaletteToggle.setAttribute("aria-expanded", "true");
  document.body.classList.add("tool-palette-open");
  window.requestAnimationFrame(() => {
    els.toolPaletteSearch.focus();
    els.toolPaletteSearch.select();
  });
}

function closeToolPalette(returnFocus = false) {
  if (!els.toolPalette || !els.toolPaletteToggle) return;
  els.toolPalette.hidden = true;
  els.toolPaletteToggle.setAttribute("aria-expanded", "false");
  document.body.classList.remove("tool-palette-open");
  if (returnFocus) els.toolPaletteToggle.focus();
}

function openToolPaletteRoute(hash) {
  if (!targetFromHash(hash)) return false;
  closeToolPalette();
  updateWorkspaceNavigator(hash);
  scrollToHash(hash, "smooth", true);
  return true;
}

