function savePortfolioReviewTrigger() {
  const config = portfolioReviewConfig();
  const reviewDate = config.reviewDate || dateInputFromDate(addDays(new Date(), 60));
  const note = `Portfolio Review Room: ${portfolioReviewFocusLabel(config.focus)} | score ${config.score}/100 | ${config.queue.length} checkpoint${config.queue.length === 1 ? "" : "s"}.`;
  config.funds.forEach((fund) => addToWatchlist(fund.id, false));
  const alerts = [
    ...config.funds.map((fund) => ({
      id: `portfolio-review-${Date.now()}-${fund.id}-${Math.random().toString(16).slice(2)}`,
      fundId: fund.id,
      trigger: "review",
      limit: reviewDate,
      note,
      createdAt: new Date().toISOString()
    })),
    ...loadAlerts()
  ].slice(0, 60);
  saveAlerts(alerts);
  renderPortfolioReviewRoom();
  renderReviewVault();
  renderInvestorRecordDesk();
  renderResearchDossier();
  renderWatchlistRoom();
  renderResearchReceipt();
  renderReceiptVault();
  renderReviewRhythmBoard();
  toast("Portfolio review trigger saved.");
}

function reviewVaultDelta(value, priorValue, suffix = "") {
  if (priorValue === null || priorValue === undefined) return "New";
  const delta = value - priorValue;
  if (Math.abs(delta) < 0.05) return `0${suffix}`;
  return `${delta > 0 ? "+" : ""}${Number.isInteger(delta) ? delta : delta.toFixed(1)}${suffix}`;
}

function researchRoundReceipt(current, entries = loadReviewVault()) {
  const validRoutes = new Set(SIMPLE_JOURNEY_STEPS.map((step) => step.value));
  let visited = [];
  try {
    const saved = JSON.parse(localStorage.getItem(SIMPLE_PROGRESS_KEY) || "[]");
    if (Array.isArray(saved)) {
      visited = [...new Set(saved.filter((route) => validRoutes.has(route)))];
    }
  } catch (error) {
    visited = [];
  }

  const visitedSet = new Set(visited);
  const completedCount = SIMPLE_JOURNEY_STEPS.filter((step) => visitedSet.has(step.value)).length;
  const isComplete = completedCount >= SIMPLE_JOURNEY_STEPS.length;
  const latestSaved = entries[0] || null;
  const nextStep = SIMPLE_JOURNEY_STEPS.find((step) => !visitedSet.has(step.value)) || SIMPLE_JOURNEY_STEPS[SIMPLE_JOURNEY_STEPS.length - 1];
  const evidenceReady = current.metrics.evidence >= 78;
  const nextReviewDate = latestSaved?.reviewDate || current.reviewDate || "Not set";
  const nextReviewDays = daysUntil(nextReviewDate);
  const nextReviewLabel = nextReviewDays === null
    ? "Review date not set"
    : nextReviewDays < 0
      ? "Review overdue"
      : nextReviewDays === 0
        ? "Review today"
        : `${nextReviewDays} days away`;
  const nextReviewMode = nextReviewDays === null
    ? "open"
    : nextReviewDays <= 7
      ? "due"
      : nextReviewDays <= 30
        ? "watch"
        : "calm";
  const nextReviewDetail = latestSaved
    ? "Saved in this browser. Keep this date as the next calm checkpoint."
    : "Save the round to lock this checkpoint into local review memory.";
  const status = isComplete ? latestSaved ? "Round saved" : "Ready to save" : "Round in progress";
  const nextLabel = isComplete ? latestSaved ? "Review rhythm" : "Save snapshot" : nextStep.label;
  const nextDetail = isComplete
    ? latestSaved
      ? `A local review memory exists. Next review: ${nextReviewDate}.`
      : "All five rooms are touched. Save one local review snapshot now."
    : `Open ${nextStep.label} before calling the research round complete.`;
  const actionKind = isComplete && !latestSaved ? "save" : "route";
  const actionRoute = isComplete && latestSaved ? "#review-rhythm" : nextStep.value;
  const actionLabel = actionKind === "save" ? "Save round" : isComplete ? "Open rhythm" : `Open ${nextStep.label}`;
  const score = clampNumber(Math.round((completedCount / SIMPLE_JOURNEY_STEPS.length) * 64 + (evidenceReady ? 18 : 8) + (latestSaved ? 18 : 0)), 0, 100);
  return {
    status,
    nextLabel,
    nextDetail,
    actionKind,
    actionRoute,
    actionLabel,
    score,
    completedCount,
    isComplete,
    evidenceReady,
    snapshotSaved: Boolean(latestSaved),
    reviewCue: {
      date: nextReviewDate,
      label: nextReviewLabel,
      mode: nextReviewMode,
      detail: nextReviewDetail,
      route: "#review-rhythm"
    },
    steps: SIMPLE_JOURNEY_STEPS.map((step) => ({
      ...step,
      done: visitedSet.has(step.value)
    })),
    metrics: [
      {
        label: "Rooms",
        value: `${completedCount}/${SIMPLE_JOURNEY_STEPS.length}`,
        detail: isComplete ? "Guided round touched" : `${SIMPLE_JOURNEY_STEPS.length - completedCount} still open`
      },
      {
        label: "Evidence",
        value: `${current.metrics.evidence}/100`,
        detail: evidenceReady ? "Source posture stronger" : "Verify source dates"
      },
      {
        label: "Snapshot",
        value: latestSaved ? "Saved" : "Preview",
        detail: latestSaved ? `${entries.length} local` : "Use Save snapshot"
      },
      {
        label: "Next",
        value: nextLabel,
        detail: nextDetail
      },
      {
        label: "Review cue",
        value: nextReviewLabel,
        detail: nextReviewDate
      }
    ]
  };
}

function renderResearchRoundReceipt(receipt) {
  return `
    <div class="review-round-receipt ${receipt.isComplete ? "complete" : "open"}">
      <div class="review-round-head">
        <div>
          <span class="metric-label">Research round receipt</span>
          <h3>${escapeHtml(receipt.status)}</h3>
          <p>${escapeHtml(receipt.nextDetail)}</p>
        </div>
        <div class="review-round-score" style="--score:${receipt.score}">
          <b>${receipt.score}</b>
          <span>Round</span>
        </div>
      </div>
      <div class="review-round-steps" aria-label="Research round steps">
        ${receipt.steps.map((step) => `
          <button class="review-round-step ${step.done ? "done" : "open"}" type="button" data-signal-route="${escapeHtml(step.value)}">
            <span>${escapeHtml(step.number)}</span>
            <strong>${escapeHtml(step.label)}</strong>
            <em>${step.done ? "Touched" : "Open"}</em>
          </button>
        `).join("")}
      </div>
      <div class="review-round-metrics">
        ${receipt.metrics.map((metric) => `
          <article>
            <span>${escapeHtml(metric.label)}</span>
            <strong>${escapeHtml(metric.value)}</strong>
            <p>${escapeHtml(metric.detail)}</p>
          </article>
        `).join("")}
      </div>
      ${receipt.snapshotSaved ? `
        <div class="review-next-cue ${escapeHtml(receipt.reviewCue.mode)}">
          <div>
            <span class="metric-label">Next review cue</span>
            <strong>${escapeHtml(receipt.reviewCue.label)}</strong>
            <p>Review date ${escapeHtml(receipt.reviewCue.date)}. ${escapeHtml(receipt.reviewCue.detail)}</p>
          </div>
          <button class="text-button review-next-action" type="button" data-signal-route="${escapeHtml(receipt.reviewCue.route)}">
            Tune rhythm
          </button>
        </div>
      ` : ""}
      <div class="review-round-actions">
        ${receipt.actionKind === "save" ? `
          <button class="text-button review-round-action" type="button" data-review-round-save>
            ${escapeHtml(receipt.actionLabel)}
          </button>
        ` : `
          <button class="text-button review-round-action" type="button" data-signal-route="${escapeHtml(receipt.actionRoute)}">
            ${escapeHtml(receipt.actionLabel)}
          </button>
        `}
      </div>
    </div>
  `;
}

function renderReviewFinishLine(snapshot, receipt) {
  if (!snapshot || !receipt.snapshotSaved) return "";
  return `
    <div class="review-finish-line" role="status" aria-live="polite">
      <div>
        <span class="metric-label">Review finish line</span>
        <strong>Saved, dated, and bounded</strong>
        <p>${escapeHtml(snapshot.score)}/100 local snapshot saved. Next review ${escapeHtml(receipt.reviewCue.date)}. This record is research memory, not an action instruction.</p>
      </div>
      <div class="review-finish-side">
        <div class="review-finish-pills" aria-label="Saved review guardrails">
          <span>Saved locally</span>
          <span>${escapeHtml(receipt.reviewCue.label)}</span>
          <span>No transaction instruction</span>
        </div>
        <button class="text-button review-next-round-action" type="button" data-review-next-round>
          Start next round
        </button>
      </div>
    </div>
  `;
}

function reviewExportPolishConfig(latest, entries, roundReceipt) {
  const fundNames = latest.funds.map((fund) => fund.name).slice(0, 4);
  const queueItems = latest.queue.slice(0, 3);
  const score = clampNumber(Math.round(
    latest.score * 0.34 +
    latest.metrics.evidence * 0.28 +
    (roundReceipt.snapshotSaved ? 18 : 8) +
    (queueItems.length <= 3 ? 12 : 6) +
    (latest.metrics.attention === 0 ? 8 : 2)
  ), 0, 100);
  const status = score >= 78 ? "Share-safe review brief" : score >= 62 ? "Review brief needs one check" : "Review brief should stay private";
  const exportId = ["NN", "REVIEW", "EXPORT", DATA_VERSION.replace(/-/g, ""), latest.id || "PREVIEW"].join("-").toUpperCase();
  const shareLines = [
    `Fund set: ${fundNames.length ? fundNames.join(" | ") : "Current preview"}`,
    `Review stance: ${latest.focusLabel} | ${latest.score}/100 | evidence ${latest.metrics.evidence}/100`,
    `Drift and TER: drift ${latest.metrics.drift.toFixed(1)}% | average TER ${latest.metrics.expense.toFixed(2)}%`,
    `Next check: ${roundReceipt.nextLabel} - ${roundReceipt.nextDetail}`,
    `Queue: ${queueItems.length ? queueItems.join(" | ") : "No major queue item in preview."}`,
    "Boundary: research memory only; no PAN, folio, CAS, bank, credential, client identifier, or action instruction."
  ];
  return {
    exportId,
    excluded: ["PAN", "folio", "CAS", "bank data", "credentials", "contact data", "private notes", "transaction instructions"],
    included: ["fund names", "review stance", "score", "evidence", "drift", "TER", "next check", "research boundary"],
    lineBudget: `${shareLines.length} calm lines`,
    score,
    shareLines,
    status,
    summary: `Saved snapshots ${entries.length}. The export stays short and keeps private-data fields out of copied review text.`,
    retention: {
      receiptId: ["NN", "REVIEW", "EXPORT", "RETENTION", DATA_VERSION.replace(/-/g, ""), latest.id || "PREVIEW"].join("-").toUpperCase(),
      verdict: entries.length ? "Retain compact review history" : "Preview only",
      rule: "Keep short review export summaries; clear browser-local snapshots when the review purpose ends or private data appears.",
      policy: [
        { label: "Keep", value: "Latest 6 snapshots", detail: "Use only score, evidence, drift, TER, fund names, queue, and review cue." },
        { label: "Delete", value: "On purpose change", detail: "Clear snapshots when the goal, fund set, or review owner changes enough to confuse the record." },
        { label: "Exclude", value: "Private fields", detail: "No PAN, folio, CAS, bank, contact, credentials, client identifiers, or private notes." },
        { label: "Move later", value: "Backend custody", detail: "Account sync should store explicit export receipts, deletion events, and review owner consent." }
      ]
    },
    memoryPersistence: {
      receiptId: ["NN", "REVIEW", "MEMORY", "PERSISTENCE", DATA_VERSION.replace(/-/g, ""), latest.id || "PREVIEW"].join("-").toUpperCase(),
      verdict: entries.length ? "Prepare account review memory" : "Preview memory only",
      cadence: "Review whenever score, evidence, TER, drift, fund set, queue, or review owner changes.",
      owner: "Review memory desk",
      rule: "Persist only compact review memory fields first; account-backed storage must add consent, deletion receipts, owner controls, and audit logs before production.",
      boundary: "Review memory must exclude PAN, folio, CAS, bank, contact, account credentials, payment data, private notes, client identifiers, and transaction instructions.",
      policy: [
        { label: "Keep", value: "Score and review cue", detail: "Retain score, evidence, drift, TER, fund set, queue cue, review date, and research boundary." },
        { label: "Sync later", value: "After owner consent", detail: "Move to account-backed review history only after the review owner accepts saved-memory controls." },
        { label: "Supersede", value: "Fund set changes", detail: "Retire or mark stale when the fund set, goal, review owner, or evidence posture changes materially." },
        { label: "Exclude", value: "Private data", detail: "Do not persist PAN, folio, CAS, account, bank, contact, credentials, payment data, or private notes." }
      ]
    }
  };
}

function renderReviewExportPolish(config) {
  return `
    <div class="review-vault-panel review-export-polish">
      <div class="review-vault-card-head">
        <div>
          <span class="metric-label">Share-safe export</span>
          <h3>${escapeHtml(config.status)}</h3>
          <p>${escapeHtml(config.summary)}</p>
        </div>
        <strong>${config.score}/100</strong>
      </div>
      <div class="review-vault-mini-grid">
        <div><span>Budget</span><b>${escapeHtml(config.lineBudget)}</b></div>
        <div><span>Included</span><b>${config.included.length}</b></div>
        <div><span>Excluded</span><b>${config.excluded.length}</b></div>
      </div>
      <div class="review-vault-mini-grid review-export-retention">
        ${config.retention.policy.map((item) => `
          <div>
            <span>${escapeHtml(item.label)}</span>
            <b>${escapeHtml(item.value)}</b>
          </div>
        `).join("")}
      </div>
      <div class="review-vault-mini-grid review-memory-persistence">
        <div><span>Memory</span><b>${escapeHtml(config.memoryPersistence.verdict)}</b></div>
        <div><span>Owner</span><b>${escapeHtml(config.memoryPersistence.owner)}</b></div>
        <div><span>Cadence</span><b>${escapeHtml(config.memoryPersistence.cadence)}</b></div>
      </div>
      <ul class="review-vault-list">
        ${config.shareLines.slice(0, 4).map((line) => `<li>${escapeHtml(line)}</li>`).join("")}
      </ul>
      <button class="text-button" type="button" data-copy-review-export-polish>Copy safe export</button>
      <button class="text-button" type="button" data-copy-review-export-retention>Copy retention</button>
      <button class="text-button" type="button" data-copy-review-memory-persistence>Copy memory note</button>
    </div>
  `;
}

function reviewSnapshotFromConfig(config) {
  return {
    id: `review-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    createdAt: new Date().toISOString(),
    release: RELEASE_LABEL,
    dataVersion: DATA_VERSION,
    focus: config.focus,
    focusLabel: portfolioReviewFocusLabel(config.focus),
    reviewDate: config.reviewDate,
    conviction: config.conviction,
    convictionLabel: portfolioReviewConvictionLabel(config.conviction),
    score: config.score,
    posture: config.posture,
    metrics: {
      avgScore: config.avgScore,
      evidence: config.avgEvidence,
      expense: Number(config.avgExpense.toFixed(2)),
      drift: Number(config.rebalance.totalAbsDrift.toFixed(1)),
      outsideBand: config.rebalance.breached.length,
      attention: config.attentionAlerts.length,
      triggers: config.alerts.length,
      queue: config.queue.length
    },
    funds: config.funds.map((fund) => ({
      id: fund.id,
      name: fund.name,
      category: fund.category,
      risk: fund.risk
    })),
    queue: config.queue.slice(0, 6),
    noteStatus: config.note ? "Written note present" : "No written note"
  };
}

function saveCurrentReviewSnapshot() {
  const config = portfolioReviewConfig();
  const snapshot = reviewSnapshotFromConfig(config);
  const entries = [snapshot, ...loadReviewVault()].slice(0, 16);
  saveReviewVault(entries);
  renderReviewVault();
  renderInvestorRecordDesk();
  renderResearchDossier();
  renderJourneyTimeline();
  renderResearchMemory();
  renderPrivacyControlRoom();
  toast("Review snapshot saved locally.");
}

function clearReviewVault() {
  saveReviewVault([]);
  renderReviewVault();
  renderInvestorRecordDesk();
  renderResearchDossier();
  renderJourneyTimeline();
  renderResearchMemory();
  renderPrivacyControlRoom();
  toast("Review vault cleared.");
}

function renderReviewVault() {
  if (!els.reviewVaultOutput || !els.reviewVaultSummary) return;
  const entries = loadReviewVault();
  const current = reviewSnapshotFromConfig(portfolioReviewConfig());
  const latest = entries[0] || null;
  const prior = entries[1] || null;
  const roundReceipt = researchRoundReceipt(current, entries);
  const scoreDelta = latest ? reviewVaultDelta(latest.score, prior?.score) : "New";
  const driftDelta = latest ? reviewVaultDelta(latest.metrics.drift, prior?.metrics.drift, "%") : "New";
  const evidenceDelta = latest ? reviewVaultDelta(latest.metrics.evidence, prior?.metrics.evidence) : "New";
  const exportPolish = reviewExportPolishConfig(latest || current, entries, roundReceipt);

  els.reviewVaultSummary.textContent = `${entries.length} snapshot${entries.length === 1 ? "" : "s"}`;

  if (!entries.length) {
    els.reviewVaultOutput.innerHTML = `
      <div class="review-vault-empty">
        <div>
          <span class="metric-label">Current review preview</span>
          <h3>${current.score}/100 ${escapeHtml(current.focusLabel)}</h3>
          <p>Save a snapshot to begin a browser-local review history. The vault stores scores, metrics, fund names, and queue items only; it does not store PAN, folio, CAS, or account data.</p>
        </div>
        <div class="review-vault-score" style="--score:${current.score}">
          <b>${current.score}</b>
          <span>Now</span>
        </div>
      </div>
      ${renderResearchRoundReceipt(roundReceipt)}
      ${renderReviewExportPolish(exportPolish)}
    `;
    return;
  }

  els.reviewVaultOutput.innerHTML = `
    <div class="review-vault-hero">
      <div>
        <span class="metric-label">Latest local snapshot</span>
        <h3>${latest.score}/100 ${escapeHtml(latest.focusLabel)}</h3>
        <p>${escapeHtml(latest.posture)} | Saved ${new Date(latest.createdAt).toLocaleString("en-IN")} | ${latest.funds.length} fund${latest.funds.length === 1 ? "" : "s"} tracked.</p>
      </div>
      <div class="review-vault-score" style="--score:${latest.score}">
        <b>${latest.score}</b>
        <span>Vault</span>
      </div>
    </div>
    ${renderResearchRoundReceipt(roundReceipt)}
    ${renderReviewFinishLine(latest, roundReceipt)}
    ${renderReviewExportPolish(exportPolish)}
    <div class="review-vault-metric-grid">
      <div><span>Score delta</span><strong>${escapeHtml(scoreDelta)}</strong></div>
      <div><span>Evidence delta</span><strong>${escapeHtml(evidenceDelta)}</strong></div>
      <div><span>Drift delta</span><strong>${escapeHtml(driftDelta)}</strong></div>
      <div><span>Latest drift</span><strong>${latest.metrics.drift.toFixed(1)}%</strong></div>
      <div><span>Attention</span><strong>${latest.metrics.attention}</strong></div>
      <div><span>Queue</span><strong>${latest.metrics.queue}</strong></div>
    </div>
    <div class="review-vault-grid">
      ${entries.slice(0, 6).map((entry, index) => {
        const previous = entries[index + 1] || null;
        return `
          <article class="review-vault-card">
            <div class="review-vault-card-head">
              <span>${escapeHtml(entry.focusLabel)}</span>
              <strong>${entry.score}/100</strong>
            </div>
            <p>${escapeHtml(entry.posture)} | Review date ${escapeHtml(entry.reviewDate)}</p>
            <div class="review-vault-mini-grid">
              <div><span>Evidence</span><b>${entry.metrics.evidence}/100</b></div>
              <div><span>Drift</span><b>${entry.metrics.drift.toFixed(1)}%</b></div>
              <div><span>TER</span><b>${entry.metrics.expense.toFixed(2)}%</b></div>
            </div>
            <small>Score ${escapeHtml(reviewVaultDelta(entry.score, previous?.score))} from prior snapshot | ${escapeHtml(entry.noteStatus)}</small>
          </article>
        `;
      }).join("")}
    </div>
    <div class="review-vault-card-grid">
      <article class="review-vault-panel">
        <h3>Latest queue</h3>
        <ul class="review-vault-list">
          ${latest.queue.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
        </ul>
      </article>
      <article class="review-vault-panel">
        <h3>Tracked funds</h3>
        <div class="review-vault-funds">
          ${latest.funds.map((fund) => `<span>${escapeHtml(fund.name)} | ${escapeHtml(fund.risk)} risk</span>`).join("")}
        </div>
      </article>
      <article class="review-vault-panel">
        <h3>Privacy rule</h3>
        <p>Snapshots stay in this browser under the NiveshNadi namespace. Do not store PAN, folio, CAS text, client data, or credentials in review notes.</p>
      </article>
    </div>
  `;
}

