function openSourceDryRunBlocker() {
  scrollToHash("#claim-release", "smooth", true);
}

function sourceReceiptSnapshotFromConfig(config = sourceDryRunBoardConfig()) {
  return sourceReceiptSnapshotFromDryRunItem(config.selected, config);
}

function sourceReceiptSnapshotFromDryRunItem(item, config = sourceDryRunBoardConfig()) {
  return {
    id: `source-receipt-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    createdAt: new Date().toISOString(),
    release: RELEASE_LABEL,
    dataVersion: DATA_VERSION,
    mode: config.mode,
    modeLabel: sourceDryRunModeLabel(config.mode),
    surface: config.surface,
    surfaceLabel: sourceDryRunSurfaceLabel(config.surface),
    source: {
      id: item.id,
      title: item.pipeline.title,
      owner: item.pipeline.owner,
      cadence: item.pipeline.cadence,
      freshnessDays: item.pipeline.freshnessDays
    },
    status: item.status,
    tone: item.tone,
    score: item.dryRunScore,
    metrics: {
      age: item.age,
      staleDays: item.staleDays,
      freshness: item.freshnessScore,
      parser: item.confidenceScore,
      citation: item.citationVisible ? 94 : 36,
      citationVisible: item.citationVisible
    },
    receipt: item.receipt,
    batch: item.batch,
    releaseSurface: item.releaseSurface,
    claimSurface: item.claimSurface,
    freezeRule: item.freezeRule,
    reviewer: item.reviewer,
    nextAction: item.nextAction,
    blockers: item.blockers.slice(0, 6),
    checks: item.checks.slice(0, 6),
    boundary: "Source receipt metadata only; excludes PAN, folio, CAS, bank, credentials, contact data, private notes, and distributor client records."
  };
}

function sourceReceiptProductionEnvelope(receipt, entries = loadSourceReceipts()) {
  const sourceSlug = (receipt.source?.id || "source").replace(/[^a-z0-9]+/gi, "").toUpperCase();
  const statusScore = receipt.status === "Release candidate" ? 92 : receipt.status === "Preview only" ? 62 : 24;
  const savedScore = entries.length ? Math.min(92, 54 + entries.length * 8) : 36;
  const readiness = Math.round(clampNumber(
    receipt.score * 0.28 +
      receipt.metrics.freshness * 0.18 +
      receipt.metrics.parser * 0.16 +
      receipt.metrics.citation * 0.14 +
      statusScore * 0.14 +
      savedScore * 0.1,
    14,
    96
  ));
  const blockers = [
    ...(!entries.length ? ["receipt has not been saved into the vault yet"] : []),
    ...(receipt.status !== "Release candidate" ? [`receipt status is ${receipt.status.toLowerCase()}`] : []),
    ...(!receipt.metrics.citationVisible ? ["visible citation path is missing"] : []),
    ...(receipt.metrics.staleDays > 0 ? [`source date is stale by ${receipt.metrics.staleDays} day${receipt.metrics.staleDays === 1 ? "" : "s"}`] : []),
    ...(receipt.metrics.parser < 72 ? ["parser confidence is below production threshold"] : []),
    ...(receipt.metrics.freshness < 72 ? ["freshness score is below production threshold"] : []),
    ...receipt.blockers.slice(0, 3)
  ];
  const status = blockers.length
    ? readiness >= 68
      ? "Reviewer release needed"
      : "Do not release"
    : readiness >= 82
      ? "Production receipt ready"
      : "Reviewer release needed";
  const tone = status === "Production receipt ready" ? "ready" : status === "Reviewer release needed" ? "watch" : "caution";
  const envelopeId = ["NN", "SOURCE", "PROD", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase();
  const metrics = [
    { label: "Envelope ID", value: envelopeId, detail: "Attach this ID to release notes and reviewer sign-off." },
    { label: "Launch verdict", value: status, detail: `Production envelope readiness ${readiness}/100.` },
    { label: "Claim surface", value: receipt.surfaceLabel, detail: receipt.releaseSurface },
    { label: "Saved proof", value: entries.length ? `${entries.length} receipt${entries.length === 1 ? "" : "s"}` : "Preview only", detail: "Saved receipts create the audit trail." }
  ];
  const productionFields = [
    { label: "source_family", value: receipt.source.title, detail: "AMFI, AMC, SID/KIM, portfolio, benchmark, TER, or riskometer family." },
    { label: "source_date_age_days", value: `${receipt.metrics.age}`, detail: `Freshness score ${receipt.metrics.freshness}/100.` },
    { label: "parser_version", value: `${DATA_VERSION}-parser`, detail: `Parser confidence ${receipt.metrics.parser}/100.` },
    { label: "citation_path", value: receipt.metrics.citationVisible ? "visible" : "missing", detail: "Investor-facing citation link or file path must be visible before launch." },
    { label: "reviewer_status", value: receipt.status, detail: receipt.reviewer },
    { label: "claim_surface", value: receipt.surfaceLabel, detail: receipt.claimSurface }
  ];
  const replaySteps = [
    `Import ${receipt.source.title} and store source URL or file hash, source date, owner, row count, parser version, and rejected-row count.`,
    "Validate required fields against the live data contract and freeze changed fields that fail parsing or citation checks.",
    "Map the receipt into Claim Surface Map and Surface Release Queue before any public score, card, X-Ray, or dossier updates.",
    "Require reviewer approval, rollback note, and correction path before the claim leaves preview.",
    "Write backend audit receipt with import timestamp, data version, reviewer status, and affected public surfaces."
  ];
  const launchSurfaces = [
    { label: "Screener and fund cards", status: receipt.status === "Release candidate" && receipt.metrics.citationVisible ? "Release candidate" : "Preview only" },
    { label: "Score and comparison", status: receipt.score >= 80 && receipt.metrics.parser >= 72 ? "Release candidate" : "Reviewer check" },
    { label: "X-Ray and portfolio", status: receipt.source.id === "portfolio-disclosure" ? "Release candidate" : "No direct change" },
    { label: "Decision pack and dossier", status: blockers.length ? "Blocked" : "Release candidate" }
  ];
  const guardrails = [
    "No live-looking value moves without source date, citation path, parser version, and reviewer status.",
    "A production receipt updates product claims only; it never stores PAN, folio, CAS, bank, contact, credential, or distributor client data.",
    "If a receipt fails, freeze the affected public surface and route it to source refresh, parser QA, citation repair, or rollback."
  ];

  return {
    blockers: blockers.length ? blockers : ["No active production blocker in this preview. Keep legal and reviewer sign-off before public launch."],
    envelopeId,
    guardrails,
    launchSurfaces,
    metrics,
    productionFields,
    readiness,
    replaySteps,
    status,
    tone
  };
}

function liveDataReadinessFocusConfig(receipt = sourceReceiptSnapshotFromConfig(), entries = loadSourceReceipts()) {
  const productionEnvelope = sourceReceiptProductionEnvelope(receipt, entries);
  const sourceSlug = (receipt.source?.id || "source").replace(/[^a-z0-9]+/gi, "").toUpperCase();
  const savedProof = entries.some((entry) => entry.id === receipt.id);
  const firstBlocker = productionEnvelope.blockers.find((blocker) => !blocker.startsWith("No active production blocker")) || "Reviewer sign-off and launch note before public refresh.";
  const proofTasks = [
    {
      label: "Source date",
      value: receipt.metrics.staleDays ? "Refresh needed" : "Visible age",
      detail: `${receipt.source.title} is ${receipt.metrics.age} day${receipt.metrics.age === 1 ? "" : "s"} old; freshness score ${receipt.metrics.freshness}/100.`,
      route: "#source-intake",
      tone: receipt.metrics.staleDays ? "caution" : "ready"
    },
    {
      label: "Citation path",
      value: receipt.metrics.citationVisible ? "Visible" : "Missing",
      detail: receipt.metrics.citationVisible ? "Investor-facing citation can be checked before trust." : "Attach source URL, file path, or citation text before any live-looking claim.",
      route: "#citation-binder",
      tone: receipt.metrics.citationVisible ? "ready" : "caution"
    },
    {
      label: "TER and expense",
      value: receipt.source.id === "risk-ter" || receipt.source.id === "amc-factsheet" ? "Direct source" : "Cross-check",
      detail: "Expense and TER values must reconcile against AMC factsheet or TER/risk feed before score cards move.",
      route: "#data-readiness",
      tone: ["risk-ter", "amc-factsheet"].includes(receipt.source.id) ? "ready" : "watch"
    },
    {
      label: "Holdings proof",
      value: receipt.source.id === "portfolio-disclosure" ? "Direct source" : "Needed before X-Ray",
      detail: "Portfolio and overlap claims need holdings disclosure date, file proof, and affected-surface mapping.",
      route: "#portfolio",
      tone: receipt.source.id === "portfolio-disclosure" ? "ready" : "watch"
    },
    {
      label: "Riskometer",
      value: receipt.source.id === "risk-ter" || receipt.source.id === "sid-kim" ? "Direct source" : "Check SID/KIM",
      detail: "Risk label, benchmark, and riskometer copy stay preview-only until SID/KIM or risk feed proof is visible.",
      route: "#readiness-gate",
      tone: ["risk-ter", "sid-kim"].includes(receipt.source.id) ? "ready" : "watch"
    }
  ];
  const readyTasks = proofTasks.filter((task) => task.tone === "ready").length;
  const blockedTasks = proofTasks.filter((task) => task.tone === "caution").length;
  const score = Math.round(clampNumber(
    productionEnvelope.readiness * 0.34 +
      receipt.score * 0.22 +
      receipt.metrics.freshness * 0.14 +
      receipt.metrics.citation * 0.12 +
      receipt.metrics.parser * 0.1 +
      (savedProof ? 8 : 0) +
      readyTasks * 2 -
      blockedTasks * 4,
    14,
    96
  ));
  const verdict = score >= 82 && !blockedTasks && productionEnvelope.status === "Production receipt ready"
    ? "Ready for reviewer release"
    : score >= 68
      ? "Live proof still needs one gate"
      : "Keep live claims in preview";
  const tone = verdict === "Ready for reviewer release" ? "ready" : verdict === "Keep live claims in preview" ? "caution" : "watch";
  const receiptId = ["NN", "LIVE", "READINESS", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase();
  const fields = [
    { label: "source_date", value: `${receipt.metrics.age}d`, detail: receipt.metrics.staleDays ? `${receipt.metrics.staleDays} stale day${receipt.metrics.staleDays === 1 ? "" : "s"}.` : "Inside current freshness rule." },
    { label: "citation_path", value: receipt.metrics.citationVisible ? "visible" : "missing", detail: "Must be investor-visible before public claim release." },
    { label: "parser_confidence", value: `${receipt.metrics.parser}/100`, detail: "Parser confidence gates extracted fields before they reach cards." },
    { label: "reviewer_status", value: receipt.status, detail: receipt.reviewer },
    { label: "claim_surface", value: receipt.surfaceLabel, detail: receipt.claimSurface }
  ];
  const retainedReceiptCount = entries.length ? Math.min(entries.length, 12) : 0;
  const retentionReview = {
    label: "Live data receipt retention",
    verdict: entries.length ? "Retain source proof trail" : "Preview retention only",
    receiptId: ["NN", "LIVE", "DATA", "RETENTION", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
    cadence: "Review whenever source date, parser, citation path, reviewer status, or claim surface changes.",
    owner: "Source receipt vault",
    boundary: "Retain source family, source date, citation status, parser version, reviewer status, claim surface, no-go reason, and release state only; exclude investor identifiers, PAN, folio, CAS, bank, contact, credentials, private notes, and distributor client data."
  };
  const retentionPolicy = [
    {
      label: "Keep",
      value: entries.length ? `Latest ${retainedReceiptCount} receipts` : "Current preview only",
      detail: "Carry compact source proof metadata forward without storing investor identity."
    },
    {
      label: "Retire",
      value: "Expired or superseded proof",
      detail: "Retire stale, failed, or replaced receipts once a newer source date and reviewer status are visible."
    },
    {
      label: "Exclude",
      value: "Private investor data",
      detail: "No PAN, folio, CAS, bank, contact, credentials, private notes, payment data, or distributor-client records."
    },
    {
      label: "Move later",
      value: "Backend receipt custody",
      detail: "Production should store explicit source receipt, delete, supersede, reviewer sign-off, and rollback events."
    }
  ];
  const custodyDeletionReview = {
    label: "Source custody deletion receipts",
    verdict: entries.length ? "Deletion route mapped" : "Preview deletion route",
    receiptId: ["NN", "SOURCE", "CUSTODY", "DELETE", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
    cadence: "Review whenever source proof expires, parser fails, citation disappears, reviewer rejects, or a public claim surface is frozen.",
    owner: "Source receipt vault",
    boundary: "Deletion receipts store source metadata, reason, affected surface, reviewer status, and replacement receipt only; they exclude investor identifiers, PAN, folio, CAS, bank, contact, credentials, payment data, private notes, and distributor-client records."
  };
  const deletionReceipts = [
    {
      label: "Supersede stale source",
      receiptId: ["NN", "SOURCE", "SUPERSEDE", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
      trigger: receipt.metrics.staleDays ? `${receipt.metrics.staleDays} stale day${receipt.metrics.staleDays === 1 ? "" : "s"}` : "Newer source date appears",
      action: "Mark old proof superseded and attach the replacement source date, parser version, citation path, and reviewer status.",
      route: "#source-intake",
      tone: receipt.metrics.staleDays ? "caution" : "watch"
    },
    {
      label: "Delete failed receipt",
      receiptId: ["NN", "SOURCE", "DELETE", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
      trigger: receipt.metrics.parser < 72 || !receipt.metrics.citationVisible ? "Parser or citation failure" : "Rejected proof row",
      action: "Delete or quarantine failed receipt metadata after a reviewer records why it cannot support a live-looking claim.",
      route: "#source-qa",
      tone: receipt.metrics.parser < 72 || !receipt.metrics.citationVisible ? "caution" : "watch"
    },
    {
      label: "Freeze claim surface",
      receiptId: ["NN", "SOURCE", "FREEZE", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
      trigger: productionEnvelope.blockers[0] || "Claim proof unclear",
      action: "Freeze affected score, card, X-Ray, dossier, or decision surface until replacement proof is accepted.",
      route: "#claim-release",
      tone: productionEnvelope.status === "Production receipt ready" ? "watch" : "caution"
    },
    {
      label: "Reviewer sign-off",
      receiptId: ["NN", "SOURCE", "DELETE", "SIGNOFF", sourceSlug, DATA_VERSION.replace(/-/g, "")].join("-").toUpperCase(),
      trigger: "Deletion or supersede action requested",
      action: "Require reviewer name, timestamp, reason, affected surface, and replacement receipt before deletion/supersede is treated as complete.",
      route: "#reviewer-workbench",
      tone: "ready"
    }
  ];
  return {
    blockedTasks,
    custodyDeletionReview,
    deletionReceipts,
    fields,
    firstBlocker,
    productionEnvelope,
    proofTasks,
    receipt,
    receiptId,
    readyTasks,
    retainedReceiptCount,
    retentionPolicy,
    retentionReview,
    savedProof,
    score,
    tone,
    verdict
  };
}

function liveDataReadinessFocusMarkup(focus) {
  return `
    <div class="live-data-readiness-focus ${escapeHtml(focus.tone)}">
      <div class="live-data-readiness-head">
        <div>
          <span>Live data readiness focus</span>
          <h3>${escapeHtml(focus.verdict)}</h3>
          <p>${escapeHtml(focus.firstBlocker)} This focus keeps source date, citation, TER, holdings, and riskometer proof in one next action.</p>
        </div>
        <div class="live-data-readiness-score" style="--score:${focus.score}">
          <b>${focus.score}</b>
          <span>Live</span>
        </div>
      </div>
      <div class="live-data-readiness-metric-grid">
        <article><span>Receipt ID</span><strong>${escapeHtml(focus.receiptId)}</strong><p>${focus.savedProof ? "Saved receipt proof is in the browser-local vault." : "Preview only until the dry-run receipt is saved."}</p></article>
        <article><span>Production envelope</span><strong>${escapeHtml(focus.productionEnvelope.status)}</strong><p>${focus.productionEnvelope.readiness}/100 live-readiness envelope.</p></article>
        <article><span>Ready checks</span><strong>${focus.readyTasks}/${focus.proofTasks.length}</strong><p>${focus.blockedTasks} hard blocker${focus.blockedTasks === 1 ? "" : "s"} in this focus.</p></article>
      </div>
      <div class="live-data-readiness-task-grid">
        ${focus.proofTasks.map((task) => `
          <article class="${escapeHtml(task.tone)}">
            <span>${escapeHtml(task.label)}</span>
            <strong>${escapeHtml(task.value)}</strong>
            <p>${escapeHtml(task.detail)}</p>
            <button class="text-button" type="button" data-build-route="${escapeHtml(task.route)}">Open proof</button>
          </article>
        `).join("")}
      </div>
      <div class="live-data-readiness-field-grid">
        ${focus.fields.map((field) => `
          <article>
            <span>${escapeHtml(field.label)}</span>
            <strong>${escapeHtml(field.value)}</strong>
            <p>${escapeHtml(field.detail)}</p>
          </article>
        `).join("")}
      </div>
      <div class="live-data-readiness-field-grid" aria-label="Live data receipt retention">
        <article>
          <span>${escapeHtml(focus.retentionReview.label)}</span>
          <strong>${escapeHtml(focus.retentionReview.verdict)}</strong>
          <p>${escapeHtml(focus.retentionReview.cadence)}</p>
        </article>
        ${focus.retentionPolicy.map((policy) => `
          <article>
            <span>${escapeHtml(policy.label)}</span>
            <strong>${escapeHtml(policy.value)}</strong>
            <p>${escapeHtml(policy.detail)}</p>
          </article>
        `).join("")}
      </div>
      <div class="live-data-readiness-field-grid" aria-label="Source custody deletion receipts">
        <article>
          <span>${escapeHtml(focus.custodyDeletionReview.label)}</span>
          <strong>${escapeHtml(focus.custodyDeletionReview.verdict)}</strong>
          <p>${escapeHtml(focus.custodyDeletionReview.cadence)}</p>
        </article>
        ${focus.deletionReceipts.map((receipt) => `
          <article class="${escapeHtml(receipt.tone)}">
            <span>${escapeHtml(receipt.label)}</span>
            <strong>${escapeHtml(receipt.trigger)}</strong>
            <p>${escapeHtml(receipt.action)}</p>
          </article>
        `).join("")}
      </div>
      <div class="live-data-readiness-actions">
        <button class="text-button" type="button" data-copy-live-data-readiness-focus>Copy live readiness</button>
        <button class="text-button" type="button" data-copy-live-data-receipt-retention>Copy live retention</button>
        <button class="text-button" type="button" data-copy-source-custody-deletion>Copy deletion receipts</button>
        <button class="text-button" type="button" data-build-route="#source-qa">Open source QA</button>
      </div>
    </div>
  `;
}

function saveCurrentSourceReceipt() {
  const snapshot = sourceReceiptSnapshotFromConfig();
  const entries = [snapshot, ...loadSourceReceipts()].slice(0, 30);
  saveSourceReceipts(entries);
  renderSourceReceiptVault();
  renderClaimSurfaceMap();
  renderSurfaceReleaseQueue();
  renderReviewerWorkbench();
  renderReviewerDecisionLedger();
  renderReviewerReleaseBinder();
  renderBackendAuditReceipts();
  renderResearchMemory();
  renderPrivacyControlRoom();
  toast("Source receipt saved locally.");
}

function clearSourceReceipts() {
  saveSourceReceipts([]);
  renderSourceReceiptVault();
  renderClaimSurfaceMap();
  renderSurfaceReleaseQueue();
  renderReviewerWorkbench();
  renderReviewerDecisionLedger();
  renderReviewerReleaseBinder();
  renderBackendAuditReceipts();
  renderResearchMemory();
  renderPrivacyControlRoom();
  toast("Source receipt vault cleared.");
}

function renderSourceReceiptVault() {
  if (!els.sourceReceiptOutput || !els.sourceReceiptSummary) return;
  const entries = loadSourceReceipts();
  const preview = sourceReceiptSnapshotFromConfig();
  const latest = entries[0] || null;
  const prior = entries[1] || null;
  const activeReceipt = latest || preview;
  const productionEnvelope = sourceReceiptProductionEnvelope(activeReceipt, entries);
  const liveDataFocus = liveDataReadinessFocusConfig(activeReceipt, entries);
  const releaseCount = entries.filter((entry) => entry.status === "Release candidate").length;
  const previewCount = entries.filter((entry) => entry.status === "Preview only").length;
  const frozenCount = entries.filter((entry) => entry.status === "Frozen").length;
  const citationGaps = entries.filter((entry) => !entry.metrics.citationVisible).length;
  const avgScore = entries.length ? Math.round(entries.reduce((sum, entry) => sum + entry.score, 0) / entries.length) : preview.score;
  const latestScoreDelta = latest ? reviewVaultDelta(latest.score, prior?.score) : "New";
  els.sourceReceiptSummary.textContent = `${entries.length} source receipt${entries.length === 1 ? "" : "s"}`;

  if (!entries.length) {
    els.sourceReceiptOutput.innerHTML = `
      <div class="source-receipt-empty">
        <div>
          <span class="metric-label">Current dry-run receipt preview</span>
          <h3>${preview.score}/100 ${escapeHtml(preview.source.title)}</h3>
          <p>Save the current Source Dry-Run receipt to create a browser-local proof trail for source date, parser confidence, citation visibility, freeze rule, reviewer handoff, and affected claim surface.</p>
        </div>
        <div class="source-receipt-score" style="--score:${preview.score}">
          <b>${preview.score}</b>
          <span>Preview</span>
        </div>
      </div>
      <div class="source-production-envelope ${escapeHtml(productionEnvelope.tone)}">
        <div class="source-production-head">
          <div>
            <span>Live data production receipt</span>
            <h3>${escapeHtml(productionEnvelope.status)}</h3>
            <p>Save the dry-run receipt before treating this production envelope as an audit-ready source proof.</p>
          </div>
          <div class="source-production-score" style="--score:${productionEnvelope.readiness}">
            <strong>${productionEnvelope.readiness}</strong>
            <span>Live</span>
          </div>
        </div>
        <div class="source-production-metric-grid">
          ${productionEnvelope.metrics.map((metric) => `
            <article>
              <span>${escapeHtml(metric.label)}</span>
              <strong>${escapeHtml(metric.value)}</strong>
              <p>${escapeHtml(metric.detail)}</p>
            </article>
          `).join("")}
        </div>
      </div>
      ${liveDataReadinessFocusMarkup(liveDataFocus)}
    `;
    return;
  }

  els.sourceReceiptOutput.innerHTML = `
    <div class="source-receipt-hero ${escapeHtml(latest.tone)}">
      <div>
        <span class="metric-label">Latest source receipt</span>
        <h3>${latest.score}/100 ${escapeHtml(latest.source.title)}</h3>
        <p>${escapeHtml(latest.status)} | ${escapeHtml(latest.surfaceLabel)} | Saved ${new Date(latest.createdAt).toLocaleString("en-IN")} | ${escapeHtml(latest.source.owner)}.</p>
      </div>
      <div class="source-receipt-score" style="--score:${latest.score}">
        <b>${latest.score}</b>
        <span>Vault</span>
      </div>
    </div>
    <div class="source-receipt-metric-grid">
      <div><span>Average score</span><strong>${avgScore}/100</strong></div>
      <div><span>Score delta</span><strong>${escapeHtml(latestScoreDelta)}</strong></div>
      <div><span>Release candidates</span><strong>${releaseCount}</strong></div>
      <div><span>Preview only</span><strong>${previewCount}</strong></div>
      <div><span>Frozen</span><strong>${frozenCount}</strong></div>
      <div><span>Citation gaps</span><strong>${citationGaps}</strong></div>
    </div>
    ${liveDataReadinessFocusMarkup(liveDataFocus)}
    <div class="source-production-envelope ${escapeHtml(productionEnvelope.tone)}">
      <div class="source-production-head">
        <div>
          <span>Live data production receipt</span>
          <h3>${escapeHtml(productionEnvelope.status)}</h3>
          <p>Bind the latest saved source receipt into a production envelope with source date, parser version, citation path, reviewer status, claim surface, and replay rules.</p>
        </div>
        <div class="source-production-score" style="--score:${productionEnvelope.readiness}">
          <strong>${productionEnvelope.readiness}</strong>
          <span>Live</span>
        </div>
      </div>
      <div class="source-production-metric-grid">
        ${productionEnvelope.metrics.map((metric) => `
          <article>
            <span>${escapeHtml(metric.label)}</span>
            <strong>${escapeHtml(metric.value)}</strong>
            <p>${escapeHtml(metric.detail)}</p>
          </article>
        `).join("")}
      </div>
      <div class="source-production-field-grid">
        ${productionEnvelope.productionFields.map((field) => `
          <article>
            <span>${escapeHtml(field.label)}</span>
            <strong>${escapeHtml(field.value)}</strong>
            <p>${escapeHtml(field.detail)}</p>
          </article>
        `).join("")}
      </div>
      <div class="source-production-surface-grid">
        ${productionEnvelope.launchSurfaces.map((surface) => `
          <article>
            <span>${escapeHtml(surface.status)}</span>
            <strong>${escapeHtml(surface.label)}</strong>
          </article>
        `).join("")}
      </div>
      <div class="source-production-two">
        <article class="${escapeHtml(productionEnvelope.tone)}">
          <span>Production blockers</span>
          <strong>${productionEnvelope.blockers.length} launch check${productionEnvelope.blockers.length === 1 ? "" : "s"}</strong>
          <ul>
            ${productionEnvelope.blockers.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
          </ul>
        </article>
        <article>
          <span>Replay sequence</span>
          <strong>Source to release trail</strong>
          <ol>
            ${productionEnvelope.replaySteps.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
          </ol>
        </article>
        <article class="source-receipt-guardrail">
          <span>Production guardrails</span>
          <strong>No silent live refresh</strong>
          <ul>
            ${productionEnvelope.guardrails.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
          </ul>
        </article>
      </div>
    </div>
    <div class="source-receipt-grid">
      ${entries.slice(0, 9).map((entry) => `
        <article class="${escapeHtml(entry.tone)}">
          <div class="source-receipt-card-head">
            <div>
              <span>${escapeHtml(entry.status)}</span>
              <strong>${escapeHtml(entry.source.title)}</strong>
            </div>
            <b>${entry.score}/100</b>
          </div>
          <p>${escapeHtml(entry.releaseSurface)}</p>
          <div class="source-receipt-mini-grid">
            <div><span>Fresh</span><b>${entry.metrics.freshness}</b></div>
            <div><span>Parser</span><b>${entry.metrics.parser}</b></div>
            <div><span>Cite</span><b>${entry.metrics.citation}</b></div>
          </div>
          <small>${escapeHtml(entry.modeLabel)} | age ${entry.metrics.age}d | ${new Date(entry.createdAt).toLocaleString("en-IN")}</small>
        </article>
      `).join("")}
    </div>
    <div class="source-receipt-panel-grid">
      <article>
        <span>Latest receipt payload</span>
        <strong>${escapeHtml(latest.receipt)}</strong>
        <p><b>Freeze rule:</b> ${escapeHtml(latest.freezeRule)}</p>
        <p><b>Next:</b> ${escapeHtml(latest.nextAction)}</p>
      </article>
      <article>
        <span>Latest blockers</span>
        <strong>${latest.blockers.length ? `${latest.blockers.length} blocker${latest.blockers.length === 1 ? "" : "s"}` : "No blockers"}</strong>
        <ul class="review-vault-list">
          ${(latest.blockers.length ? latest.blockers : ["No active blocker captured for this receipt."]).map((blocker) => `<li>${escapeHtml(blocker)}</li>`).join("")}
        </ul>
      </article>
      <article class="source-receipt-guardrail">
        <span>Vault boundary</span>
        <strong>No investor identity</strong>
        <p>${escapeHtml(latest.boundary)}</p>
      </article>
    </div>
  `;
}

function makeSourceReceiptVaultBrief() {
  const entries = loadSourceReceipts();
  const preview = sourceReceiptSnapshotFromConfig();
  const latest = entries[0] || preview;
  const prior = entries[1] || null;
  const productionEnvelope = sourceReceiptProductionEnvelope(latest, entries);
  const liveDataFocus = liveDataReadinessFocusConfig(latest, entries);
  return [
    "# NiveshNadi Source Receipt Vault",
    `Release: ${RELEASE_LABEL} (${DATA_VERSION})`,
    `Saved source receipts: ${entries.length}`,
    `Latest source: ${latest.source.title}`,
    `Latest status: ${latest.status}`,
    `Latest score: ${latest.score}/100`,
    `Score delta: ${reviewVaultDelta(latest.score, prior?.score)}`,
    `Surface: ${latest.surfaceLabel}`,
    `Reviewer: ${latest.reviewer}`,
    "",
    "## Live Data Readiness Focus",
    `Receipt ID: ${liveDataFocus.receiptId}`,
    `Verdict: ${liveDataFocus.verdict}`,
    `Readiness score: ${liveDataFocus.score}/100`,
    `First blocker: ${liveDataFocus.firstBlocker}`,
    `Saved proof: ${liveDataFocus.savedProof ? "yes" : "no"}`,
    "Proof tasks:",
    ...liveDataFocus.proofTasks.map((task) => `- ${task.label}: ${task.value} | ${task.detail} | Route ${task.route}`),
    "Required fields:",
    ...liveDataFocus.fields.map((field) => `- ${field.label}: ${field.value} | ${field.detail}`),
    "",
    "## Live Data Receipt Retention",
    `Retention receipt: ${liveDataFocus.retentionReview.receiptId}`,
    `Verdict: ${liveDataFocus.retentionReview.verdict}`,
    `Cadence: ${liveDataFocus.retentionReview.cadence}`,
    `Owner: ${liveDataFocus.retentionReview.owner}`,
    `Boundary: ${liveDataFocus.retentionReview.boundary}`,
    ...liveDataFocus.retentionPolicy.map((policy) => `- ${policy.label}: ${policy.value} | ${policy.detail}`),
    "",
    "## Source Custody Deletion Receipts",
    `Deletion receipt: ${liveDataFocus.custodyDeletionReview.receiptId}`,
    `Verdict: ${liveDataFocus.custodyDeletionReview.verdict}`,
    `Cadence: ${liveDataFocus.custodyDeletionReview.cadence}`,
    `Owner: ${liveDataFocus.custodyDeletionReview.owner}`,
    `Boundary: ${liveDataFocus.custodyDeletionReview.boundary}`,
    ...liveDataFocus.deletionReceipts.map((item) => `- ${item.label}: ${item.receiptId} | Trigger: ${item.trigger} | Action: ${item.action} | Route ${item.route}`),
    "",
    "## Live Data Production Receipt",
    `Envelope ID: ${productionEnvelope.envelopeId}`,
    `Verdict: ${productionEnvelope.status}`,
    `Production readiness: ${productionEnvelope.readiness}/100`,
    "Production fields:",
    ...productionEnvelope.productionFields.map((field) => `- ${field.label}: ${field.value} | ${field.detail}`),
    "Launch surfaces:",
    ...productionEnvelope.launchSurfaces.map((surface) => `- ${surface.label}: ${surface.status}`),
    "Replay sequence:",
    ...productionEnvelope.replaySteps.map((step, index) => `${index + 1}. ${step}`),
    "Production blockers:",
    ...productionEnvelope.blockers.map((blocker) => `- ${blocker}`),
    "Guardrails:",
    ...productionEnvelope.guardrails.map((item) => `- ${item}`),
    "",
    "## Latest Receipt",
    `Receipt: ${latest.receipt}`,
    `Batch: ${latest.batch}`,
    `Source age: ${latest.metrics.age} days`,
    `Freshness: ${latest.metrics.freshness}/100`,
    `Parser: ${latest.metrics.parser}/100`,
    `Citation visible: ${latest.metrics.citationVisible ? "yes" : "no"}`,
    `Freeze rule: ${latest.freezeRule}`,
    `Next action: ${latest.nextAction}`,
    "",
    "## Latest Blockers",
    ...(latest.blockers.length ? latest.blockers.map((blocker) => `- ${blocker}`) : ["- No active blocker captured."]),
    "",
    "## Recent Source Receipts",
    ...(entries.length ? entries.slice(0, 10).map((entry) => `- ${new Date(entry.createdAt).toLocaleString("en-IN")}: ${entry.score}/100, ${entry.source.title}, ${entry.status}, ${entry.surfaceLabel}`) : ["- No saved source receipts yet. This brief uses the current dry-run preview."]),
    "",
    "## Guardrail",
    "Source Receipt Vault stores source metadata only. It is not investment advice, suitability approval, execution approval, or a return guarantee. It excludes PAN, folio, CAS, bank data, credentials, contact data, private notes, and distributor client records."
  ].join("\n");
}

