    "import_gate_id",
    "worker_id",
    "runbook_id",
    "event_name",
    "idempotency_key",
    "pause_state",
    "retry_count",
    "source_url_hash",
    "checksum",
    "source_date",
    "parser_version",
    "schema_version",
    "accepted_row_count",
    "rejected_row_count",
    "rejected_row_digest_id",
    "alert_route_id",
    "delivery_attempt_id",
    "reviewer_queue_id",
    "failed_run_event_store_id",
    "rollback_evidence_id",
    "affected_surface_ids",
    "acceptance_status"
