function bindSectionNavigation() {
  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    link.addEventListener("click", (event) => {
      const hash = link.getAttribute("href");
      if (!targetFromHash(hash)) return;
      event.preventDefault();
      scrollToHash(hash, "smooth", true);
    });
  });

  window.addEventListener("hashchange", () => {
    if (targetFromHash(window.location.hash)) {
      settleHashNavigation();
    }
  });
}

function bindFloatingSearch() {
  if (!els.floatingSearchToggle || !els.floatingSearchPanel || !els.floatingSearchInput) return;
  const isEditableTarget = (target) => target instanceof Element
    && Boolean(target.closest("input, textarea, select, [contenteditable='true'], [contenteditable='']"));
  const setOpen = (isOpen, returnFocus = false) => {
    els.floatingSearchPanel.hidden = !isOpen;
    els.floatingSearchToggle.classList.toggle("is-open", isOpen);
    els.floatingSearchToggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
    if (isOpen && window.innerWidth > 680) {
      els.floatingSearchInput.focus();
      els.floatingSearchInput.select();
    } else if (!isOpen && returnFocus) {
      els.floatingSearchToggle.focus({ preventScroll: true });
    }
  };

  els.floatingSearchToggle.addEventListener("click", () => {
    const shouldOpen = els.floatingSearchPanel.hidden;
    setOpen(shouldOpen);
    if (shouldOpen) {
      scrollToHash("#screener");
    }
  });

  els.floatingSearchClose?.addEventListener("click", () => setOpen(false, true));
  els.floatingSearchInput.addEventListener("input", (event) => {
    syncSearchInputs(event.target.value);
  });
  els.floatingSearchInput.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      setOpen(false, true);
    }
  });
  els.floatingSearchPanel.addEventListener("click", (event) => {
    if (event.target.closest("a")) setOpen(false);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !els.floatingSearchPanel.hidden) {
      event.preventDefault();
      setOpen(false, true);
    }
    if (!event.altKey && !event.ctrlKey && !event.metaKey && event.key === "/" && !isEditableTarget(event.target)) {
      event.preventDefault();
      scrollToHash("#screener");
      window.requestAnimationFrame(() => {
        els.searchInput?.focus({ preventScroll: true });
        els.searchInput?.select();
      });
    }
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
      event.preventDefault();
      setOpen(true);
    }
  });
}

function bindScrollTopButton() {
  if (!els.scrollTopButton) return;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const updateVisibility = () => {
    const isVisible = window.scrollY > 460;
    els.scrollTopButton.classList.toggle("is-visible", isVisible);
    els.scrollTopButton.setAttribute("aria-hidden", isVisible ? "false" : "true");
    els.scrollTopButton.tabIndex = isVisible ? 0 : -1;
  };
  els.scrollTopButton.addEventListener("click", () => {
    window.scrollTo({
      top: 0,
      behavior: reduceMotion.matches ? "auto" : "smooth"
    });
  });
  window.addEventListener("scroll", updateVisibility, { passive: true });
  window.addEventListener("resize", updateVisibility);
  updateVisibility();
}

function bindToolPalette() {
  if (!els.toolPaletteToggle || !els.toolPalette || !els.toolPaletteSearch || !els.toolPaletteResults) return;
  const focusResult = (step = 1) => {
    const buttons = Array.from(els.toolPaletteResults.querySelectorAll(".tool-palette-result"));
    if (!buttons.length) return;
    const currentIndex = buttons.indexOf(document.activeElement);
    const nextIndex = currentIndex < 0 ? 0 : (currentIndex + step + buttons.length) % buttons.length;
    buttons[nextIndex].focus();
  };

  els.toolPaletteToggle.addEventListener("click", () => {
    if (els.toolPalette.hidden) openToolPalette();
    else closeToolPalette(true);
  });

  els.toolPaletteSearch.addEventListener("input", (event) => {
    renderToolPaletteResults(event.target.value);
  });

  els.toolPaletteSearch.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeToolPalette(true);
    }
    if (event.key === "Enter") {
      const firstRoute = els.toolPaletteResults.querySelector(".tool-palette-result")?.dataset.toolPaletteRoute;
      if (firstRoute) {
        event.preventDefault();
        openToolPaletteRoute(firstRoute);
      }
    }
    if (event.key === "ArrowDown") {
      event.preventDefault();
      focusResult(1);
    }
  });

  els.toolPaletteResults.addEventListener("click", (event) => {
    const route = event.target.closest("[data-tool-palette-route]")?.dataset.toolPaletteRoute;
    if (route) openToolPaletteRoute(route);
  });

  els.toolPaletteResults.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      closeToolPalette(true);
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      focusResult(event.key === "ArrowDown" ? 1 : -1);
    }
    if (event.key === "Enter" || event.key === " ") {
      const route = document.activeElement?.dataset?.toolPaletteRoute;
      if (route) {
        event.preventDefault();
        openToolPaletteRoute(route);
      }
    }
  });

  document.addEventListener("click", (event) => {
    if (els.toolPalette.hidden || event.target.closest(".workspace-command") || event.target.closest(".tool-palette")) return;
    closeToolPalette();
  });

  window.addEventListener("hashchange", () => closeToolPalette());
  renderToolPaletteResults();
}

function bindWorkspaceJump() {
  if (!els.workspaceJump) return;
  buildWorkspaceOptionIndex();
  renderWorkspaceJumpForMode(window.location.hash || "#screener");
  renderToolPaletteResults();
  let scrollFrame = 0;
  const syncFromScroll = () => {
    scrollFrame = 0;
    if (Date.now() < state.hashSettleUntil && targetFromHash(window.location.hash)) {
      updateWorkspaceNavigator(window.location.hash);
      return;
    }
    updateWorkspaceNavigator(workspaceHashFromViewport());
  };
  const queueScrollSync = () => {
    if (scrollFrame) return;
    scrollFrame = window.requestAnimationFrame(syncFromScroll);
  };
  els.navLinks?.forEach((link) => {
    link.addEventListener("click", (event) => {
      const hash = link.getAttribute("href");
      if (!hash || !targetFromHash(hash)) return;
      event.preventDefault();
      updateWorkspaceNavigator(hash);
      scrollToHash(hash, "smooth", true);
    });
  });
  els.workspaceJump.addEventListener("change", () => {
    const hash = els.workspaceJump.value;
    if (!hash) return;
    updateWorkspaceNavigator(hash);
    scrollToHash(hash, "smooth", true);
  });
  els.deskRailNext?.addEventListener("click", () => {
    const hash = els.deskRailNext.dataset.railNext;
    if (!hash) return;
    updateWorkspaceNavigator(hash);
    scrollToHash(hash, "smooth", true);
  });
  els.deskRailBack?.addEventListener("click", () => {
    const hash = els.deskRailBack.dataset.railBack;
    if (!hash) return;
    updateWorkspaceNavigator(hash);
    scrollToHash(hash, "smooth", true);
  });
  els.deskRailRecent?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-rail-recent]");
    if (!button || button.disabled) return;
    const hash = button.dataset.railRecent;
    if (!hash) return;
    updateWorkspaceNavigator(hash);
    scrollToHash(hash, "smooth", true);
  });
  els.deskRail?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-rail-collapse]");
    if (!button || !els.deskRail.contains(button)) return;
    toggleDeskRailGroupCollapse(button.dataset.railCollapse);
  });
  els.deskRailSwitcher?.addEventListener("click", (event) => {
    const button = event.target.closest("[data-rail-group]");
    if (!button) return;
    const hash = button.dataset.railGroup;
    if (!hash) return;
    updateWorkspaceNavigator(hash);
    scrollToHash(hash, "smooth", true);
  });
  bindDeskRailKeyboard();
  window.addEventListener("hashchange", () => {
    if (targetFromHash(window.location.hash)) {
      settleHashNavigation();
      return;
    }
    updateWorkspaceNavigator(window.location.hash);
  });
  window.addEventListener("scroll", queueScrollSync, { passive: true });
  window.addEventListener("resize", queueScrollSync);
  updateWorkspaceNavigator(window.location.hash || "#screener");
}

